export default function AuthLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return <>{children}</>;
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Eye, EyeOff, Sun, Moon, HardHat } from "lucide-react";
import Link from "next/link";

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState("admin@engetech.com.br");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // 1. Estado para controlar se o componente foi montado no cliente
  const [mounted, setMounted] = useState(false);

  const [isDark, setIsDark] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;

    const saved = localStorage.getItem("engetech-theme");
    const prefersDark = window.matchMedia(
      "(prefers-color-scheme: dark)",
    ).matches;

    return saved ? saved === "dark" : prefersDark;
  });

  // 2. useEffect para marcar como montado assim que carregar no navegador
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setMounted(true);
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute(
      "data-theme",
      isDark ? "dark" : "light",
    );
  }, [isDark]);

  function toggleTheme() {
    const next = !isDark;
    setIsDark(next);
    localStorage.setItem("engetech-theme", next ? "dark" : "light");
    document.documentElement.setAttribute(
      "data-theme",
      next ? "dark" : "light",
    );
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "Erro ao fazer login");
        return;
      }
      router.push("/dashboard");
    } catch {
      setError("Erro de conexão com o servidor");
    } finally {
      setLoading(false);
    }
  }

  const inp: React.CSSProperties = {
    width: "100%",
    border: "1px solid var(--border-input)",
    borderRadius: "var(--radius-sm)",
    padding: "10px 12px",
    fontSize: "14px",
    fontFamily: "inherit",
    background: "var(--bg-input)",
    color: "var(--text-primary)",
    outline: "none",
    transition: "border-color 150ms, box-shadow 150ms",
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "var(--bg-app)",
        transition: "background var(--transition-slow)",
      }}
    >
      {/* Botão tema */}
      <button
        onClick={toggleTheme}
        style={{
          position: "fixed",
          top: "16px",
          right: "16px",
          background: "var(--bg-card)",
          border: "1px solid var(--border)",
          borderRadius: "var(--radius-full)",
          padding: "8px",
          cursor: "pointer",
          color: "var(--text-secondary)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: "var(--shadow-sm)",
          transition: "all var(--transition)",
          width: "34px", // Adicionando tamanho fixo para evitar pulos no layout
          height: "34px",
        }}
      >
        {/* 3. Renderização condicional segura para Hydration */}
        {mounted ? isDark ? <Sun size={16} /> : <Moon size={16} /> : null}
      </button>

      {/* Card de login */}
      <div
        style={{
          background: "var(--bg-card)",
          border: "1px solid var(--border)",
          borderRadius: "var(--radius-lg)",
          padding: "40px 36px",
          width: "360px",
          maxWidth: "95vw",
          boxShadow: "var(--shadow-lg)",
          animation: "modalIn 300ms ease",
        }}
      >
        {/* Logo */}
        <div style={{ textAlign: "center", marginBottom: "28px" }}>
          <div
            style={{
              width: "48px",
              height: "48px",
              borderRadius: "var(--radius)",
              background: "var(--primary-light)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              margin: "0 auto 14px",
            }}
          >
            <HardHat size={24} color="var(--primary)" />
          </div>
          <div
            style={{
              fontSize: "20px",
              fontWeight: 700,
              letterSpacing: "-0.3px",
            }}
          >
            <span style={{ color: "var(--primary)" }}>Engetech</span>
            <span style={{ color: "var(--text-primary)" }}> Soluções</span>
          </div>
          <div
            style={{
              fontSize: "13px",
              color: "var(--text-muted)",
              marginTop: "4px",
            }}
          >
            Sistema de gestão de obras
          </div>
        </div>

        <form onSubmit={handleSubmit}>
          {/* Email */}
          <div style={{ marginBottom: "14px" }}>
            <label
              style={{
                fontSize: "13px",
                fontWeight: 500,
                color: "var(--text-secondary)",
                display: "block",
                marginBottom: "6px",
              }}
            >
              E-mail
            </label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              style={inp}
              placeholder="seu@email.com"
            />
          </div>

          {/* Senha */}
          <div style={{ marginBottom: "20px" }}>
            <label
              style={{
                fontSize: "13px",
                fontWeight: 500,
                color: "var(--text-secondary)",
                display: "block",
                marginBottom: "6px",
              }}
            >
              Senha
            </label>
            <div style={{ position: "relative" }}>
              <input
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                placeholder="••••••••"
                style={{ ...inp, paddingRight: "42px" }}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                style={{
                  position: "absolute",
                  right: "12px",
                  top: "50%",
                  transform: "translateY(-50%)",
                  background: "none",
                  border: "none",
                  cursor: "pointer",
                  color: "var(--text-muted)",
                  padding: "2px",
                  display: "flex",
                  alignItems: "center",
                }}
              >
                {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
          </div>

          {/* Erro */}
          {error && (
            <div
              style={{
                background: "var(--danger-light)",
                border: "1px solid var(--danger)",
                borderRadius: "var(--radius-sm)",
                padding: "10px 12px",
                fontSize: "13px",
                color: "var(--danger-text)",
                marginBottom: "14px",
                display: "flex",
                alignItems: "center",
                gap: "8px",
              }}
            >
              ⚠ {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            style={{
              width: "100%",
              background: loading ? "var(--text-muted)" : "var(--primary)",
              color: "#fff",
              border: "none",
              borderRadius: "var(--radius-sm)",
              padding: "11px",
              fontSize: "14px",
              fontWeight: 600,
              cursor: loading ? "not-allowed" : "pointer",
              fontFamily: "inherit",
              transition: "background var(--transition)",
              boxShadow: loading
                ? "none"
                : "0 2px 8px hsl(213, 70%, 39%, 0.35)",
            }}
          >
            {loading ? "Entrando..." : "Entrar no sistema"}
          </button>
        </form>

        <p
          style={{
            fontSize: "11px",
            color: "var(--text-muted)",
            textAlign: "center",
            marginTop: "20px",
          }}
        >
          Acesso restrito — Engetech Soluções LTDA
        </p>

        <p
          style={{
            textAlign: "center",
            marginTop: 20,
            fontSize: 14,
            color: "#6b7280",
          }}
        >
          Não tem conta?{" "}
          <Link href="/cadastro" style={{ color: "#1B5FA6", fontWeight: 600 }}>
            Criar conta grátis
          </Link>
        </p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  Search,
  Users,
  Building2,
  Mail,
  Shield,
  ShieldOff,
  Trash2,
  RefreshCw,
  UserCheck,
  ChevronDown,
} from "lucide-react";

interface Usuario {
  id: string;
  name: string;
  email: string;
  empresa: string | null;
  role: string;
  createdAt: string;
  _count: { obras: number };
}

export default function AdminUsuariosPage() {
  const [usuarios, setUsuarios] = useState<Usuario[]>([]);
  const [loading, setLoading] = useState(true);
  const [busca, setBusca] = useState("");
  const [filtroRole, setFiltroRole] = useState("todos");
  const [acao, setAcao] = useState<string | null>(null);

  async function recarregar() {
    setLoading(true);
    try {
      const res = await fetch("/api/admin/usuarios");
      if (!res.ok) throw new Error();
      setUsuarios(await res.json());
    } catch {
      alert("Acesso negado ou erro ao carregar.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    let ativo = true;
    async function buscar() {
      setLoading(true);
      try {
        const res = await fetch("/api/admin/usuarios");
        if (!res.ok) throw new Error();
        const data = await res.json();
        if (ativo) setUsuarios(data);
      } catch {
        if (ativo) alert("Acesso negado ou erro ao carregar.");
      } finally {
        if (ativo) setLoading(false);
      }
    }
    buscar();
    return () => {
      ativo = false;
    };
  }, []);

  async function alterarRole(id: string, novoRole: string) {
    setAcao(id);
    try {
      await fetch(`/api/admin/usuarios/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ role: novoRole }),
      });
      await recarregar();
    } finally {
      setAcao(null);
    }
  }

  async function excluir(id: string, nome: string) {
    if (!confirm(`Excluir "${nome}"? Esta ação não pode ser desfeita.`)) return;
    setAcao(id);
    try {
      await fetch(`/api/admin/usuarios/${id}`, { method: "DELETE" });
      await recarregar();
    } finally {
      setAcao(null);
    }
  }

  const filtrados = usuarios.filter((u) => {
    const termo = busca.toLowerCase();
    const bate =
      u.name.toLowerCase().includes(termo) ||
      u.email.toLowerCase().includes(termo) ||
      (u.empresa ?? "").toLowerCase().includes(termo);
    return bate && (filtroRole === "todos" || u.role === filtroRole);
  });

  const totais = {
    total: usuarios.length,
    admins: usuarios.filter((u) => u.role === "admin").length,
    users: usuarios.filter((u) => u.role === "user").length,
  };

  return (
    <div style={s.page}>
      <div style={s.header}>
        <div>
          <h1 style={s.title}>Usuários cadastrados</h1>
          <p style={s.subtitle}>Gerencie acessos e permissões da plataforma</p>
        </div>
        <button onClick={recarregar} style={s.btnRefresh}>
          <RefreshCw size={16} /> Atualizar
        </button>
      </div>

      <div style={s.metrics}>
        <Metric
          icon={<Users size={20} />}
          label="Total"
          value={totais.total}
          color="#1B5FA6"
        />
        <Metric
          icon={<UserCheck size={20} />}
          label="Usuários"
          value={totais.users}
          color="#16a34a"
        />
        <Metric
          icon={<Shield size={20} />}
          label="Admins"
          value={totais.admins}
          color="#9333ea"
        />
      </div>

      <div style={s.filtros}>
        <div style={s.searchWrap}>
          <Search size={15} style={{ color: "#9ca3af", flexShrink: 0 }} />
          <input
            style={s.search}
            placeholder="Buscar por nome, e-mail ou empresa..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
          />
        </div>
        <div style={s.selectWrap}>
          <select
            style={s.select}
            value={filtroRole}
            onChange={(e) => setFiltroRole(e.target.value)}
          >
            <option value="todos">Todos os perfis</option>
            <option value="user">Usuário</option>
            <option value="admin">Admin</option>
          </select>
          <ChevronDown
            size={14}
            style={{
              position: "absolute",
              right: 10,
              top: "50%",
              transform: "translateY(-50%)",
              color: "#6b7280",
              pointerEvents: "none",
            }}
          />
        </div>
      </div>

      <div style={s.tableWrap}>
        {loading ? (
          <div style={s.empty}>Carregando...</div>
        ) : filtrados.length === 0 ? (
          <div style={s.empty}>Nenhum usuário encontrado.</div>
        ) : (
          <table style={s.table}>
            <thead>
              <tr>
                <th style={s.th}>Usuário</th>
                <th style={s.th}>Empresa</th>
                <th style={s.th}>Obras</th>
                <th style={s.th}>Cadastro</th>
                <th style={s.th}>Perfil</th>
                <th style={{ ...s.th, textAlign: "right" }}>Ações</th>
              </tr>
            </thead>
            <tbody>
              {filtrados.map((u) => (
                <tr key={u.id} style={s.tr}>
                  <td style={s.td}>
                    <div style={s.userCell}>
                      <div style={avatar(u.role)}>
                        {u.name.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <div style={s.userName}>{u.name}</div>
                        <div style={s.userEmail}>
                          <Mail size={11} style={{ marginRight: 3 }} />
                          {u.email}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td style={s.td}>
                    <div style={s.empresa}>
                      {u.empresa ? (
                        <>
                          <Building2 size={13} style={{ color: "#9ca3af" }} />
                          {u.empresa}
                        </>
                      ) : (
                        <span style={{ color: "#d1d5db" }}>—</span>
                      )}
                    </div>
                  </td>
                  <td style={s.td}>
                    <span style={s.obras}>{u._count.obras}</span>
                  </td>
                  <td style={s.td}>
                    <span style={s.data}>
                      {new Date(u.createdAt).toLocaleDateString("pt-BR")}
                    </span>
                  </td>
                  <td style={s.td}>
                    <span style={badge(u.role)}>
                      {u.role === "admin" ? "👑 Admin" : "👤 Usuário"}
                    </span>
                  </td>
                  <td style={{ ...s.td, textAlign: "right" }}>
                    <div style={s.acoes}>
                      {u.role !== "admin" ? (
                        <button
                          onClick={() => alterarRole(u.id, "admin")}
                          disabled={acao === u.id}
                          style={{ ...s.btnAcao, color: "#9333ea" }}
                          title="Tornar admin"
                        >
                          <Shield size={14} />
                        </button>
                      ) : (
                        <button
                          onClick={() => alterarRole(u.id, "user")}
                          disabled={acao === u.id}
                          style={{ ...s.btnAcao, color: "#f59e0b" }}
                          title="Remover admin"
                        >
                          <ShieldOff size={14} />
                        </button>
                      )}
                      <button
                        onClick={() => excluir(u.id, u.name)}
                        disabled={acao === u.id}
                        style={{ ...s.btnAcao, color: "#dc2626" }}
                        title="Excluir"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
      <p style={s.footer}>
        Mostrando {filtrados.length} de {totais.total} usuários
      </p>
    </div>
  );
}

function Metric({
  icon,
  label,
  value,
  color,
}: {
  icon: React.ReactNode;
  label: string;
  value: number;
  color: string;
}) {
  return (
    <div style={s.metric}>
      <div style={{ ...s.metricIcon, background: color + "18", color }}>
        {icon}
      </div>
      <div>
        <div style={s.metricValue}>{value}</div>
        <div style={s.metricLabel}>{label}</div>
      </div>
    </div>
  );
}

