function avatar(role: string): React.CSSProperties {
  return {
    width: 36,
    height: 36,
    borderRadius: "50%",
    background: role === "admin" ? "#9333ea22" : "#1B5FA618",
    color: role === "admin" ? "#9333ea" : "#1B5FA6",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontSize: 15,
    fontWeight: 700,
    flexShrink: 0,
  };
}

function badge(role: string): React.CSSProperties {
  return {
    display: "inline-flex",
    alignItems: "center",
    gap: 4,
    padding: "3px 10px",
    borderRadius: 20,
    fontSize: 12,
    fontWeight: 600,
    background: role === "admin" ? "#9333ea18" : "#16a34a18",
    color: role === "admin" ? "#9333ea" : "#16a34a",
  };
}

"use client";

import { useEffect, useState } from "react";
import * as S from "@/lib/styles";

interface Cliente {
  id: string;
  nome: string;
  segmento: string;
  classificacao: string;
  whatsapp: string;
  email: string;
  clienteDesde: string;
  observacoes: string;
}

const SEGMENTOS = ["residencial", "comercial", "industrial"];
const CLASSIFICACOES = ["novo", "recorrente", "fidelizado"];

const classColors: Record<string, { bg: string; color: string }> = {
  fidelizado: { bg: "#EEEDFE", color: "#3C3489" },
  recorrente: { bg: "#E6F1FB", color: "#0C447C" },
  novo: { bg: "#E1F5EE", color: "#085041" },
};

function maskTelefone(v: string) {
  const d = v.replace(/\D/g, "").slice(0, 11);
  if (d.length <= 10)
    return d.replace(/^(\d{2})(\d)/, "($1) $2").replace(/(\d{4})(\d)/, "$1-$2");
  return d
    .replace(/^(\d{2})(\d)/, "($1) $2")
    .replace(/(\d{1})(\d{4})(\d)/, "$1 $2-$3");
}

const formVazio = {
  nome: "",
  segmento: "residencial",
  classificacao: "novo",
  whatsapp: "",
  email: "",
  clienteDesde: "",
  observacoes: "",
};

export default function ClientesPage() {
  const [clientes, setClientes] = useState<Cliente[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [form, setForm] = useState(formVazio);

  async function loadData() {
    const res = await fetch("/api/clientes");
    const data = await res.json();
    setClientes(Array.isArray(data) ? data : []);
    setLoading(false);
  }

  useEffect(() => {
    let ativo = true;
    async function buscar() {
      const res = await fetch("/api/clientes");
      const data = await res.json();
      if (ativo) {
        setClientes(Array.isArray(data) ? data : []);
        setLoading(false);
      }
    }
    buscar();
    return () => {
      ativo = false;
    };
  }, []);

  function handleChange(
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  }

  function handleWhatsapp(e: React.ChangeEvent<HTMLInputElement>) {
    setForm((prev) => ({ ...prev, whatsapp: maskTelefone(e.target.value) }));
  }

  function abrirEdicao(c: Cliente) {
    setEditandoId(c.id);
    setForm({
      nome: c.nome,
      segmento: c.segmento,
      classificacao: c.classificacao,
      whatsapp: c.whatsapp || "",
      email: c.email || "",
      clienteDesde: c.clienteDesde || "",
      observacoes: c.observacoes || "",
    });
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function cancelarForm() {
    setShowForm(false);
    setEditandoId(null);
    setForm(formVazio);
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    if (editandoId) {
      await fetch(`/api/clientes/${editandoId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
    } else {
      await fetch("/api/clientes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
    }
    cancelarForm();
    setSaving(false);
    loadData();
  }

  async function excluir(id: string) {
    await fetch(`/api/clientes/${id}`, { method: "DELETE" });
    setConfirmDelete(null);
    loadData();
  }

  if (loading)
    return <div style={{ color: "var(--text-muted)" }}>Carregando...</div>;

  return (
    <div>
      {confirmDelete && (
        <div style={S.modal}>
