            className={styles.kpiDesktopValue}
            style={{ color: obrasAtrasadas > 0 ? 'var(--red, #ef4444)' : undefined }}
          >
            {obrasAtrasadas}
          </span>
          <span className={styles.kpiDesktopLabel}>Obras atrasadas</span>
        </div>
