/* dashboard.module.css */

.page {
  background: var(--bg);
  min-height: 100%;
  font-family: var(--font);
  color: var(--fg);
  -webkit-font-smoothing: antialiased;
}

/* ── Header ─────────────────────────────────────────── */
.header {
  background: var(--navy);
  color: #fff;
  padding: 12px 20px 20px;
}

.headerRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.greeting {
  font-size: 13px;
  opacity: 0.7;
  margin: 0 0 2px;
}

.userName {
  font-size: 20px;
  font-weight: 700;
  margin: 0;
}

.headerActions {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-shrink: 0;
}

.notifBtn {
  position: relative;
  width: 36px;
  height: 36px;
  background: rgba(255, 255, 255, 0.1);
  border: none;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  padding: 0;
}

.badge {
  position: absolute;
  top: -2px;
  right: -2px;
  min-width: 16px;
  height: 16px;
  background: #ef4444;
  border-radius: 8px;
  font-size: 10px;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--navy);
  padding: 0 2px;
}

.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--navy-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  color: #fff;
  border: 2px solid rgba(255, 255, 255, 0.2);
  flex-shrink: 0;
  user-select: none;
}

/* ── KPI Strip ──────────────────────────────────────── */
.kpiStrip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--navy-light);
  border-radius: 0 0 20px 20px;
  overflow: hidden;
  margin-bottom: 20px;
}

.kpiCell {
  background: var(--navy-mid);
  padding: 14px 8px;
  text-align: center;
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.kpiValue {
  font-size: 18px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.kpiGreen { color: var(--green); }
.kpiRed   { color: #f87171; }

.kpiLabel {
  font-size: 10px;
  opacity: 0.6;
}

/* ── Body ───────────────────────────────────────────── */
.body {
  padding: 0 16px;
}

/* ── Section ────────────────────────────────────────── */
.section {
  margin-bottom: 24px;
}

.sectionHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.sectionTitle {
  font-size: 16px;
  font-weight: 700;
  margin: 0;
}

.sectionSub {
  font-size: 12px;
  color: var(--fg-2);
  display: block;
  margin-top: 1px;
}

.seeAll {
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 3px;
  white-space: nowrap;
}

/* ── Metric Card ────────────────────────────────────── */
.metricCard {
  background: var(--card);
  border-radius: var(--radius);
  border: 1px solid var(--card-border);
  box-shadow: var(--shadow);
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 14px;
}

.metricIcon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.metricIcon.red    { background: var(--red-dim); }
.metricIcon.orange { background: var(--orange-dim); }
.metricIcon.green  { background: var(--green-dim); }

.metricPct {
  font-size: 26px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  display: block;
  line-height: 1;
}
.metricPct.red    { color: var(--red); }
.metricPct.orange { color: var(--orange); }
.metricPct.green  { color: var(--green); }

.metricLabel {
  font-size: 13px;
  color: var(--fg-2);
  margin: 3px 0 1px;
}

.metricSub {
  font-size: 11px;
  color: var(--fg-3);
  margin: 0;
}

/* ── Obras Carousel ─────────────────────────────────── */
.obrasScroll {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scrollbar-width: none;
  /* negative margin + padding trick para o scroll ir borda a borda */
  margin-left: -16px;
  margin-right: -16px;
  padding-left: 16px;
  padding-right: 16px;
  padding-bottom: 4px;
}
.obrasScroll::-webkit-scrollbar { display: none; }

.obraCard {
  min-width: 260px;
  background: var(--navy);
  border-radius: var(--radius);
  overflow: hidden;
  flex-shrink: 0;
  position: relative;
  cursor: pointer;
  text-decoration: none;
  transition: transform 0.15s;
  display: block;
}
.obraCard:active { transform: scale(0.97); }

.obraCardBg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #142236 0%, #0d1b2e 100%);
}

.obraCardContent {
  position: relative;
  padding: 16px;
}

.obraCardIcon {
  width: 44px;
  height: 44px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 40px;
}

.obraAbbr {
  position: absolute;
  right: 16px;
  top: 16px;
  font-size: 28px;
  font-weight: 900;
  color: rgba(255, 255, 255, 0.08);
  letter-spacing: -1px;
  user-select: none;
}

.obraCardName {
  color: #fff;
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.obraCardClient {
  color: rgba(255, 255, 255, 0.55);
  font-size: 12px;
  margin: 0 0 12px;
}

.obraPct {
  color: #fff;
  font-size: 20px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  margin: 0 0 4px;
}

.obraValue {
  color: rgba(255, 255, 255, 0.55);
  font-size: 12px;
  margin: 0 0 8px;
}

.progressBar {
  height: 4px;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 2px;
  overflow: hidden;
}

.progressFill {
  height: 100%;
  border-radius: 2px;
  transition: width 0.4s ease;
}

/* ── Empty state ────────────────────────────────────── */
.emptyState {
  background: var(--card);
  border: 1px dashed var(--card-border);
  border-radius: var(--radius);
  min-width: 260px;
  padding: 32px 20px;
  text-align: center;
  color: var(--fg-2);
  font-size: 14px;
}
.emptyLink {
  display: inline-block;
  margin-top: 10px;
  color: var(--accent);
  font-weight: 600;
  font-size: 13px;
  text-decoration: none;
}

/* ── Atalhos ────────────────────────────────────────── */
.atalhos {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.atalhoBtn {
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 14px 6px;
  cursor: pointer;
  transition: transform 0.12s;
  text-decoration: none;
  color: var(--fg);
}
.atalhoBtn:active { transform: scale(0.94); }

.atalhoIcon {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.atalhoLabel {
  font-size: 11px;
  font-weight: 600;
  color: var(--fg-2);
  text-align: center;
  line-height: 1.2;
}

/* ── Tablet / Desktop ───────────────────────────────── */
@media (min-width: 640px) {
  .kpiStrip {
    border-radius: 12px;
    margin: -1px 16px 20px;
  }

