// app/(dashboard)/dashboard/page.tsx
import { cookies } from "next/headers";
import { verifyToken } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import DashboardClient from "./DashboardClient";

export default async function DashboardPage() {
  const cookieStore = await cookies();
  const token = cookieStore.get("engetech-token")?.value ?? "";
  const payload = verifyToken(token);

  // Seu JWT retorna { userId, email, role } — usamos userId como tenantId
  const tenantId =
    (payload as { tenantId?: string; userId?: string } | null)?.tenantId ??
    (payload as { userId?: string } | null)?.userId ??
    "";

  // Busca obras e usuário em paralelo
  const [obras, usuario] = await Promise.all([
    prisma.obra.findMany({
      where: { tenantId },
      select: {
        id: true,
        centroCusto: true, // nome da obra no seu schema
        status: true,
        contrato: true, // valorContrato → contrato
        inicio: true, // dataInicio → inicio
        cliente: { select: { nome: true } },
        etapas: {
          select: { percentual: true },
        },
      },
      orderBy: { createdAt: "desc" },
      take: 10,
    }),
    // Model é User, campo name (não nome)
    prisma.user.findFirst({
      where: { id: tenantId },
      select: { name: true },
    }),
  ]);

  // Calcula progresso médio a partir das etapas (não existe campo progresso)
  const obrasComProgresso = obras.map((o) => {
    const pct =
      o.etapas.length > 0
        ? Math.round(
            o.etapas.reduce(
              (acc: number, e: { percentual: number }) => acc + e.percentual,
              0,
            ) / o.etapas.length,
          )
        : 0;
    return {
      id: o.id,
      nome: o.centroCusto, // usa centroCusto como nome da obra
      status: o.status,
      progresso: pct,
      valorContrato: o.contrato,
      dataInicio: o.inicio,
      cliente: o.cliente,
    };
  });

  // KPIs
  const obrasAtivas = obrasComProgresso.filter((o) =>
    ["EM_ANDAMENTO", "PLANEJAMENTO"].includes(o.status),
  ).length;

  const caixaMes = null as number | null;

  return (
    <DashboardClient
      obras={obrasComProgresso}
      obrasAtivas={obrasAtivas}
      caixaMes={caixaMes}
      nomeUsuario={usuario?.name ?? "Usuário"}
    />
  );
}

"use client";

import { useEffect, useState } from "react";
import * as S from "@/lib/styles";

interface Obra {
  id: string;
  centroCusto: string;
  cliente: { nome: string };
}
interface Diarista {
  id: string;
  nome: string;
  funcao: string;
  telefone: string;
  obra: Obra;
}
interface Pagamento {
  id: string;
  diarista: Diarista;
  obra: Obra;
  diasTrab: number;
  valorDia: number;
  total: number;
  status: string;
}

function formatMoney(v: number) {
  return v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

export default function DiaristasPage() {
  const [diaristas, setDiaristas] = useState<Diarista[]>([]);
  const [pagamentos, setPagamentos] = useState<Pagamento[]>([]);
  const [obras, setObras] = useState<Obra[]>([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<"diaristas" | "pagamentos">("diaristas");
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [formD, setFormD] = useState({
    nome: "",
    funcao: "",
    telefone: "",
    obraId: "",
  });
  const [formP, setFormP] = useState({
    diaristaId: "",
    obraId: "",
    diasTrab: "",
    valorDia: "",
    status: "pendente",
  });

  async function loadData() {
    const [d, p, o] = await Promise.all([
      fetch("/api/diaristas").then((r) => r.json()),
      fetch("/api/pagamentos").then((r) => r.json()),
      fetch("/api/obras").then((r) => r.json()),
    ]);
    setDiaristas(Array.isArray(d) ? d : []);
    setPagamentos(Array.isArray(p) ? p : []);
    setObras(Array.isArray(o) ? o : []);
    setLoading(false);
  }

  useEffect(() => {
    async function init() {
      await loadData();
    }
    init();
  }, []);

  async function handleSubmitDiarista(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    await fetch("/api/diaristas", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(formD),
    });
    setFormD({ nome: "", funcao: "", telefone: "", obraId: "" });
    setShowForm(false);
    setSaving(false);
    loadData();
  }

  async function handleSubmitPagamento(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    const d = diaristas.find((d) => d.id === formP.diaristaId);
    await fetch("/api/pagamentos", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...formP, obraId: d?.obra?.id || formP.obraId }),
    });
    setFormP({
      diaristaId: "",
      obraId: "",
      diasTrab: "",
      valorDia: "",
      status: "pendente",
    });
    setShowForm(false);
    setSaving(false);
    loadData();
  }

  const totalPago = pagamentos
    .filter((p) => p.status === "pago")
    .reduce((a, p) => a + p.total, 0);
  const totalPendente = pagamentos
    .filter((p) => p.status === "pendente")
    .reduce((a, p) => a + p.total, 0);

  if (loading)
    return <div style={{ color: "var(--text-muted)" }}>Carregando...</div>;

  return (
    <div>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3,1fr)",
          gap: "12px",
          marginBottom: "16px",
