      >
        {[
          {
            label: "Diaristas cadastrados",
            value: String(diaristas.length),
            color: "var(--blue)",
          },
          {
            label: "Total pago",
            value: formatMoney(totalPago),
            color: "var(--green)",
          },
          {
            label: "Pendente pagar",
            value: formatMoney(totalPendente),
            color: "var(--amber)",
          },
        ].map((m) => (
          <div key={m.label} style={S.metricCard}>
            <div
              style={{
                fontSize: "11px",
                color: "var(--text-secondary)",
                marginBottom: "4px",
                textTransform: "uppercase",
                letterSpacing: "0.04em",
              }}
            >
              {m.label}
            </div>
            <div style={{ fontSize: "20px", fontWeight: 700, color: m.color }}>
              {m.value}
            </div>
          </div>
        ))}
      </div>

      <div
        style={{
          display: "flex",
          gap: "4px",
          background: "var(--bg-tertiary)",
          borderRadius: "8px",
          padding: "3px",
          width: "fit-content",
          marginBottom: "14px",
        }}
      >
        {(["diaristas", "pagamentos"] as const).map((t) => (
          <button
            key={t}
            onClick={() => {
              setTab(t);
              setShowForm(false);
            }}
            style={{
              border: "none",
              background: tab === t ? "var(--bg-primary)" : "transparent",
              padding: "6px 16px",
              borderRadius: "6px",
              fontSize: "13px",
              fontWeight: tab === t ? 600 : 400,
              color:
                tab === t ? "var(--text-primary)" : "var(--text-secondary)",
              cursor: "pointer",
              fontFamily: "inherit",
            }}
          >
            {t === "diaristas" ? "👷 Diaristas" : "💰 Pagamentos"}
          </button>
        ))}
      </div>

      <div
        style={{
          display: "flex",
          justifyContent: "flex-end",
          marginBottom: "12px",
        }}
      >
        <button
          onClick={() => setShowForm(!showForm)}
          style={{
            ...S.btnPrimary,
            background: showForm ? "var(--text-muted)" : "var(--blue)",
          }}
        >
          {showForm
            ? "Cancelar"
            : tab === "diaristas"
              ? "+ Novo Diarista"
              : "+ Registrar Pagamento"}
        </button>
      </div>

      {showForm && tab === "diaristas" && (
        <div style={{ ...S.card, marginBottom: "16px" }}>
          <h3
            style={{
              fontSize: "14px",
              fontWeight: 600,
              marginBottom: "16px",
              color: "var(--text-primary)",
