                />
              </div>
              <div>
                <label style={S.label}>Obra</label>
                <select
                  value={formD.obraId}
                  onChange={(e) =>
                    setFormD((p) => ({ ...p, obraId: e.target.value }))
                  }
                  required
                  style={S.input}
                >
                  <option value="">Selecione...</option>
                  {obras.map((o) => (
                    <option key={o.id} value={o.id}>
