                  ))}
                </select>
              </div>
            </div>
            <button
              type="submit"
              disabled={saving}
              style={{
                ...S.btnPrimary,
                marginTop: "16px",
                opacity: saving ? 0.6 : 1,
              }}
            >
              {saving ? "Salvando..." : "Salvar Diarista"}
            </button>
          </form>
        </div>
      )}

      {showForm && tab === "pagamentos" && (
        <div style={{ ...S.card, marginBottom: "16px" }}>
          <h3
            style={{
              fontSize: "14px",
              fontWeight: 600,
              marginBottom: "16px",
              color: "var(--text-primary)",
            }}
          >
            Registrar Pagamento
          </h3>
          <form onSubmit={handleSubmitPagamento}>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: "12px",
              }}
            >
              <div>
                <label style={S.label}>Diarista</label>
                <select
                  value={formP.diaristaId}
                  onChange={(e) =>
                    setFormP((p) => ({ ...p, diaristaId: e.target.value }))
                  }
                  required
                  style={S.input}
                >
                  <option value="">Selecione...</option>
                  {diaristas.map((d) => (
                    <option key={d.id} value={d.id}>
                      {d.nome} — {d.funcao}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label style={S.label}>Dias trabalhados</label>
                <input
                  type="number"
                  value={formP.diasTrab}
                  onChange={(e) =>
                    setFormP((p) => ({ ...p, diasTrab: e.target.value }))
                  }
                  required
                  placeholder="Ex: 5"
                  style={S.input}
                />
              </div>
              <div>
                <label style={S.label}>Valor por dia (R$)</label>
                <input
                  type="number"
                  value={formP.valorDia}
                  onChange={(e) =>
                    setFormP((p) => ({ ...p, valorDia: e.target.value }))
                  }
                  required
                  placeholder="Ex: 180"
                  style={S.input}
                />
              </div>
              <div>
                <label style={S.label}>Status</label>
                <select
                  value={formP.status}
                  onChange={(e) =>
                    setFormP((p) => ({ ...p, status: e.target.value }))
                  }
                  style={S.input}
                >
                  <option value="pendente">Pendente</option>
                  <option value="pago">Pago</option>
                </select>
              </div>
            </div>
            {formP.diasTrab && formP.valorDia && (
              <div
                style={{
                  marginTop: "10px",
                  background: "var(--bg-tertiary)",
                  borderRadius: "8px",
                  padding: "10px 14px",
                  fontSize: "13px",
                  color: "var(--blue)",
                  fontWeight: 600,
                }}
              >
                Total:{" "}
                {formatMoney(Number(formP.diasTrab) * Number(formP.valorDia))}
              </div>
            )}
            <button
              type="submit"
              disabled={saving}
              style={{
                ...S.btnPrimary,
                marginTop: "16px",
                opacity: saving ? 0.6 : 1,
              }}
            >
              {saving ? "Salvando..." : "Salvar Pagamento"}
            </button>
          </form>
        </div>
      )}

      {tab === "diaristas" && (
        <div style={S.card}>
          {diaristas.length === 0 ? (
            <p style={{ fontSize: "13px", color: "var(--text-muted)" }}>
              Nenhum diarista cadastrado.
            </p>
          ) : (
            <table style={S.table}>
              <thead>
                <tr>
                  {["Nome", "Função", "Telefone", "Obra"].map((h) => (
                    <th key={h} style={S.th}>
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {diaristas.map((d) => (
                  <tr key={d.id}>
                    <td style={{ ...S.td, fontWeight: 600 }}>{d.nome}</td>
                    <td style={S.td}>{d.funcao}</td>
                    <td style={S.td}>{d.telefone || "—"}</td>
                    <td style={S.td}>{d.obra?.centroCusto}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
