                            <span
                              style={{
                                fontSize: "10px",
                                fontWeight: 600,
                                color: "#fff",
                                whiteSpace: "nowrap",
                              }}
                            >
                              {g.percentual}%
                            </span>
                          </div>
                        )}
                        {/* Linha de hoje */}
                        {pctHoje && (
                          <div
                            style={{
                              position: "absolute",
                              top: 0,
                              bottom: 0,
                              left: `${pctHoje}%`,
                              width: "2px",
                              background: "#E24B4A",
                              zIndex: 10,
                            }}
                          />
                        )}
                      </div>
                      {/* Badge status */}
                      <div style={{ marginLeft: "10px", flexShrink: 0 }}>
                        <span
                          style={{
                            ...st,
                            padding: "2px 7px",
                            borderRadius: "10px",
                            fontSize: "10px",
                            fontWeight: 600,
                          }}
                        >
                          {g.status}
                        </span>
                      </div>
                    </div>
                  );
                })}

                {/* Legenda */}
                <div
                  style={{
                    display: "flex",
                    gap: "16px",
                    marginTop: "12px",
                    paddingLeft: "160px",
                    fontSize: "11px",
                    color: "#888",
                  }}
                >
                  <span
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "4px",
                    }}
                  >
                    <span
                      style={{
                        width: "12px",
                        height: "6px",
                        background: "#185FA522",
                        border: "1px solid #185FA555",
                        borderRadius: "2px",
                        display: "inline-block",
                      }}
                    />
                    Previsto
                  </span>
                  <span
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "4px",
                    }}
                  >
                    <span
                      style={{
                        width: "12px",
                        height: "6px",
                        background: "#185FA5",
                        borderRadius: "2px",
                        display: "inline-block",
                      }}
                    />
                    Realizado
                  </span>
                  <span
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "4px",
                    }}
                  >
                    <span
                      style={{
                        width: "2px",
                        height: "12px",
                        background: "#E24B4A",
                        display: "inline-block",
                      }}
                    />
                    Hoje
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* Gráfico de causas */}
          {ocorrencias.length > 0 && (
            <div
              style={{
                marginTop: "24px",
                borderTop: "1px solid #f0f0f0",
                paddingTop: "16px",
