                Causas de atraso
              </h3>
              <ResponsiveContainer width="100%" height={160}>
                <BarChart data={causasData()} layout="vertical">
                  <XAxis
                    type="number"
                    allowDecimals={false}
                    tick={{ fontSize: 11 }}
                  />
                  <YAxis
                    type="category"
                    dataKey="causa"
                    width={140}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar dataKey="count" name="Ocorrências" radius={[0, 4, 4, 0]}>
                    {causasData().map((_, i) => (
                      <Cell
                        key={i}
                        fill={
                          [
                            "#E24B4A",
                            "#F59E0B",
                            "#185FA5",
                            "#8B5CF6",
                            "#1D9E75",
                            "#6B7280",
                          ][i % 6]
                        }
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>
      )}

      {/* ===== ETAPAS ===== */}
      {tab === "etapas" && (
        <div>
          <div
            style={{
              display: "flex",
              justifyContent: "flex-end",
              marginBottom: "12px",
