          >
            <button
              onClick={() => setShowFormEtapa(!showFormEtapa)}
              style={{
                background: "#185FA5",
                color: "#fff",
                border: "none",
                borderRadius: "8px",
                padding: "9px 16px",
                fontSize: "13px",
                fontWeight: 600,
                cursor: "pointer",
                fontFamily: "inherit",
              }}
            >
              {showFormEtapa ? "Cancelar" : "+ Nova Etapa"}
            </button>
          </div>

          {showFormEtapa && (
            <div
              style={{
                background: "#fff",
                border: "1px solid #e0e0e0",
                borderRadius: "10px",
                padding: "20px",
                marginBottom: "16px",
              }}
            >
              <h3
                style={{
                  fontSize: "14px",
                  fontWeight: 600,
                  marginBottom: "16px",
                }}
              >
                Cadastrar Etapa
              </h3>
              <form onSubmit={salvarEtapa}>
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "1fr 1fr",
                    gap: "12px",
                  }}
                >
                  <div>
                    <label style={lbl}>Nome da etapa</label>
                    <input
                      value={formEtapa.nome}
                      onChange={(e) =>
                        setFormEtapa((p) => ({ ...p, nome: e.target.value }))
                      }
                      required
                      placeholder="Ex: Demolição e Preparo"
                      style={inp}
                    />
                  </div>
                  <div>
                    <label style={lbl}>Ordem</label>
                    <input
                      type="number"
                      value={formEtapa.ordem}
                      onChange={(e) =>
                        setFormEtapa((p) => ({ ...p, ordem: e.target.value }))
                      }
                      required
                      placeholder="Ex: 1"
                      style={inp}
                    />
                  </div>
                  <div>
                    <label style={lbl}>Status</label>
                    <select
                      value={formEtapa.status}
                      onChange={(e) =>
                        setFormEtapa((p) => ({ ...p, status: e.target.value }))
                      }
                      style={inp}
                    >
                      <option value="pendente">Pendente</option>
                      <option value="andamento">Em andamento</option>
                      <option value="atraso">Com atraso</option>
                      <option value="concluido">Concluído</option>
                    </select>
                  </div>
                  <div>
                    <label style={lbl}>Percentual concluído (%)</label>
                    <input
                      type="number"
                      min="0"
                      max="100"
                      value={formEtapa.percentual}
                      onChange={(e) =>
                        setFormEtapa((p) => ({
                          ...p,
                          percentual: e.target.value,
                        }))
                      }
                      style={inp}
                    />
                  </div>
                  <div>
                    <label style={lbl}>Início planejado</label>
                    <input
                      type="date"
                      value={formEtapa.inicioPlano}
                      onChange={(e) =>
                        setFormEtapa((p) => ({
                          ...p,
                          inicioPlano: e.target.value,
                        }))
                      }
                      required
                      style={inp}
                    />
                  </div>
                  <div>
                    <label style={lbl}>Fim planejado</label>
                    <input
                      type="date"
                      value={formEtapa.fimPlano}
                      onChange={(e) =>
                        setFormEtapa((p) => ({
                          ...p,
                          fimPlano: e.target.value,
                        }))
                      }
                      required
                      style={inp}
                    />
                  </div>
                  <div>
                    <label style={lbl}>Início real (opcional)</label>
                    <input
                      type="date"
                      value={formEtapa.inicioReal}
                      onChange={(e) =>
                        setFormEtapa((p) => ({
                          ...p,
                          inicioReal: e.target.value,
                        }))
                      }
                      style={inp}
                    />
                  </div>
                  <div>
                    <label style={lbl}>Fim real (opcional)</label>
                    <input
                      type="date"
                      value={formEtapa.fimReal}
                      onChange={(e) =>
                        setFormEtapa((p) => ({ ...p, fimReal: e.target.value }))
                      }
                      style={inp}
                    />
                  </div>
                </div>
                <button
                  type="submit"
                  disabled={saving}
                  style={{
                    marginTop: "16px",
                    background: saving ? "#93c0e8" : "#185FA5",
                    color: "#fff",
                    border: "none",
                    borderRadius: "8px",
                    padding: "10px 20px",
                    fontSize: "13px",
                    fontWeight: 600,
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  {saving ? "Salvando..." : "Salvar Etapa"}
                </button>
              </form>
            </div>
          )}

          {/* Lista de etapas */}
          {etapas.length === 0 ? (
            <div
              style={{
                background: "#fff",
                border: "1px solid #e0e0e0",
                borderRadius: "10px",
                padding: "30px",
                textAlign: "center",
                color: "#aaa",
                fontSize: "13px",
              }}
            >
              Nenhuma etapa cadastrada. Clique em &quot;+ Nova Etapa&quot; para
              começar.
