          ) : (
            etapas.map((etapa) => {
              const st = STATUS_COLORS[etapa.status] || STATUS_COLORS.pendente;
              const aberto = abertos[etapa.id];
              return (
                <div
                  key={etapa.id}
                  style={{
                    background: "#fff",
                    border: "1px solid #e0e0e0",
                    borderRadius: "10px",
                    marginBottom: "8px",
                    overflow: "hidden",
                  }}
                >
                  {/* Header da etapa */}
                  <div
                    onClick={() =>
                      setAbertos((p) => ({ ...p, [etapa.id]: !p[etapa.id] }))
                    }
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "12px",
                      padding: "12px 16px",
                      cursor: "pointer",
                      background: "#f8f8f6",
                    }}
                  >
                    <div
                      style={{
                        width: "8px",
                        height: "8px",
                        borderRadius: "50%",
                        background: st.color,
                        flexShrink: 0,
                      }}
                    />
                    <div style={{ flex: 1, fontWeight: 600, fontSize: "13px" }}>
                      {etapa.nome}
                    </div>
                    <span
                      style={{
                        ...st,
                        padding: "2px 8px",
                        borderRadius: "10px",
                        fontSize: "11px",
                        fontWeight: 600,
