                            );
                          })}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      )}

      {/* ===== OCORRÊNCIAS ===== */}
      {tab === "ocorrencias" && (
        <div>
          <div
            style={{
              display: "flex",
              justifyContent: "flex-end",
              marginBottom: "12px",
            }}
          >
            <button
              onClick={() => setShowFormOcorrencia(!showFormOcorrencia)}
              style={{
                background: "#E24B4A",
                color: "#fff",
                border: "none",
                borderRadius: "8px",
                padding: "9px 16px",
                fontSize: "13px",
                fontWeight: 600,
                cursor: "pointer",
                fontFamily: "inherit",
              }}
            >
              {showFormOcorrencia ? "Cancelar" : "⚠ Registrar Ocorrência"}
            </button>
          </div>

          {showFormOcorrencia && (
            <div
              style={{
                background: "#fff",
                border: "1px solid #e0e0e0",
                borderRadius: "10px",
                padding: "20px",
                marginBottom: "16px",
              }}
            >
              <h3
                style={{
                  fontSize: "14px",
                  fontWeight: 600,
                  marginBottom: "16px",
                }}
              >
                Registrar Ocorrência de Atraso
              </h3>
              <form onSubmit={salvarOcorrencia}>
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "1fr 1fr",
                    gap: "12px",
                  }}
                >
                  <div>
                    <label style={lbl}>Causa</label>
                    <select
                      value={formOcorrencia.causa}
                      onChange={(e) =>
                        setFormOcorrencia((p) => ({
                          ...p,
                          causa: e.target.value,
                        }))
                      }
                      style={inp}
                    >
                      {CAUSAS.map((c) => (
                        <option key={c} value={c}>
                          {c}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label style={lbl}>Dias de atraso</label>
                    <input
                      type="number"
                      min="0"
                      value={formOcorrencia.diasAtraso}
                      onChange={(e) =>
                        setFormOcorrencia((p) => ({
                          ...p,
                          diasAtraso: e.target.value,
                        }))
                      }
                      placeholder="Ex: 3"
                      style={inp}
                    />
                  </div>
                  <div style={{ gridColumn: "1/-1" }}>
                    <label style={lbl}>Descrição do ocorrido</label>
                    <input
                      value={formOcorrencia.descricao}
                      onChange={(e) =>
                        setFormOcorrencia((p) => ({
                          ...p,
                          descricao: e.target.value,
                        }))
                      }
                      required
                      placeholder="Descreva o que aconteceu..."
                      style={inp}
                    />
                  </div>
                  <div>
                    <label style={lbl}>Data</label>
                    <input
                      type="date"
                      value={formOcorrencia.data}
                      onChange={(e) =>
                        setFormOcorrencia((p) => ({
                          ...p,
                          data: e.target.value,
                        }))
                      }
                      style={inp}
                    />
                  </div>
                </div>
                <button
                  type="submit"
                  disabled={saving}
                  style={{
                    marginTop: "16px",
                    background: saving ? "#e89393" : "#E24B4A",
                    color: "#fff",
                    border: "none",
                    borderRadius: "8px",
                    padding: "10px 20px",
                    fontSize: "13px",
                    fontWeight: 600,
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  {saving ? "Salvando..." : "Salvar Ocorrência"}
                </button>
              </form>
            </div>
          )}

          {ocorrencias.length === 0 ? (
            <div
              style={{
                background: "#fff",
                border: "1px solid #e0e0e0",
                borderRadius: "10px",
                padding: "30px",
                textAlign: "center",
                color: "#aaa",
                fontSize: "13px",
              }}
            >
              ✅ Nenhuma ocorrência registrada nesta obra.
            </div>
          ) : (
            <div
              style={{
                background: "#fff",
                border: "1px solid #e0e0e0",
                borderRadius: "10px",
                padding: "18px 20px",
              }}
            >
              <table
                style={{
                  width: "100%",
                  borderCollapse: "collapse",
                  fontSize: "13px",
                }}
              >
                <thead>
                  <tr>
                    {["Data", "Causa", "Descrição", "Dias de atraso"].map(
                      (h) => (
                        <th
                          key={h}
                          style={{
                            textAlign: "left",
                            padding: "0 0 10px 0",
                            fontSize: "11px",
                            fontWeight: 600,
                            color: "#888",
                            borderBottom: "1px solid #e0e0e0",
                          }}
                        >
                          {h}
                        </th>
                      ),
                    )}
                  </tr>
                </thead>
                <tbody>
                  {ocorrencias.map((o) => (
                    <tr key={o.id}>
                      <td
                        style={{
                          padding: "10px 0",
                          borderBottom: "1px solid #f0f0f0",
                          color: "#888",
                        }}
                      >
                        {new Date(o.data).toLocaleDateString("pt-BR")}
                      </td>
                      <td
                        style={{
                          padding: "10px 0",
                          borderBottom: "1px solid #f0f0f0",
                        }}
                      >
                        <span
                          style={{
                            background: "#FCEBEB",
                            color: "#791F1F",
                            padding: "2px 8px",
                            borderRadius: "10px",
                            fontSize: "11px",
                            fontWeight: 600,
                          }}
                        >
                          {o.causa}
                        </span>
                      </td>
                      <td
                        style={{
                          padding: "10px 0",
                          borderBottom: "1px solid #f0f0f0",
                          color: "#555",
                        }}
                      >
                        {o.descricao}
                      </td>
                      <td
                        style={{
                          padding: "10px 0",
                          borderBottom: "1px solid #f0f0f0",
                          fontWeight: 700,
                          color: o.diasAtraso > 0 ? "#E24B4A" : "#888",
                        }}
                      >
                        {o.diasAtraso > 0 ? `+${o.diasAtraso} dias` : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { gerarRelatorioPDF } from "@/lib/gerarRelatorioPDF";
import * as S from "@/lib/styles";

interface Cliente {
  id: string;
  nome: string;
}
interface Obra {
  id: string;
  centroCusto: string;
  tipo: string;
  status: string;
  contrato: number;
  orcamentoMat: number;
  orcamentoMO: number;
  gastoMat: number;
  gastoMO: number;
  gastoEsporadico: number;
  inicio: string;
  previsaoFim: string;
  cliente: Cliente;
}

const TIPOS = ["residencial", "comercial", "industrial"];
const STATUS = ["andamento", "execucao", "finalizada", "pausada"];

const TIPO_COLORS: Record<string, { bg: string; color: string }> = {
  residencial: { bg: "#E6F1FB", color: "#0C447C" },
  comercial: { bg: "#EAF3DE", color: "#27500A" },
  industrial: { bg: "#FAEEDA", color: "#633806" },
};
const STATUS_COLORS: Record<string, { bg: string; color: string }> = {
  andamento: { bg: "#E6F1FB", color: "#0C447C" },
  execucao: { bg: "#FAEEDA", color: "#633806" },
  finalizada: { bg: "#EAF3DE", color: "#27500A" },
  pausada: { bg: "#FCEBEB", color: "#791F1F" },
};

function formatMoney(v: number) {
  return v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function Badge({
  label,
  bg,
  color,
}: {
  label: string;
  bg: string;
  color: string;
}) {
  return (
    <span
      style={{
        background: bg,
        color,
        padding: "2px 9px",
        borderRadius: "10px",
        fontSize: "11px",
        fontWeight: 600,
      }}
    >
      {label}
    </span>
  );
}

export default function ObrasPage() {
  const router = useRouter();
  const [obras, setObras] = useState<Obra[]>([]);
  const [clientes, setClientes] = useState<Cliente[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [gerandoPDF, setGerandoPDF] = useState<string | null>(null);

  // Estado adicionado para o link do portal
  const [linkGerado, setLinkGerado] = useState<string | null>(null);

  const [form, setForm] = useState({
    centroCusto: "",
    clienteId: "",
    tipo: "residencial",
    status: "andamento",
    inicio: "",
    previsaoFim: "",
    contrato: "",
    orcamentoMat: "",
    orcamentoMO: "",
  });

  async function fetchObrasEClientes() {
    const [obrasRes, clientesRes] = await Promise.all([
      fetch("/api/obras"),
      fetch("/api/clientes"),
    ]);
    const oData = await obrasRes.json();
    const cData = await clientesRes.json();
    return {
      obras: Array.isArray(oData) ? oData : [],
      clientes: Array.isArray(cData) ? cData : [],
    };
  }

  async function loadData() {
    const { obras: obrasData, clientes: clientesData } =
      await fetchObrasEClientes();
    setObras(obrasData);
    setClientes(clientesData);
    setLoading(false);
  }

  useEffect(() => {
    let ativo = true;
    async function buscar() {
      const [obrasRes, clientesRes] = await Promise.all([
        fetch("/api/obras"),
        fetch("/api/clientes"),
      ]);
      const oData = await obrasRes.json();
      const cData = await clientesRes.json();
      if (ativo) {
        setObras(Array.isArray(oData) ? oData : []);
        setClientes(Array.isArray(cData) ? cData : []);
        setLoading(false);
      }
    }
    buscar();
    return () => {
      ativo = false;
    };
  }, []);

  function handleChange(
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  }

  function abrirEdicao(obra: Obra) {
    setEditandoId(obra.id);
    setForm({
      centroCusto: obra.centroCusto,
      clienteId: obra.cliente?.id || "",
      tipo: obra.tipo,
      status: obra.status,
      inicio: obra.inicio?.slice(0, 10) || "",
      previsaoFim: obra.previsaoFim?.slice(0, 10) || "",
      contrato: String(obra.contrato),
      orcamentoMat: String(obra.orcamentoMat),
      orcamentoMO: String(obra.orcamentoMO),
    });
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function cancelarForm() {
    setShowForm(false);
    setEditandoId(null);
    setForm({
      centroCusto: "",
      clienteId: "",
      tipo: "residencial",
      status: "andamento",
      inicio: "",
      previsaoFim: "",
      contrato: "",
      orcamentoMat: "",
      orcamentoMO: "",
    });
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    const body = {
      ...form,
      contrato: Number(form.contrato),
      orcamentoMat: Number(form.orcamentoMat),
      orcamentoMO: Number(form.orcamentoMO),
    };
    if (editandoId) {
      await fetch(`/api/obras/${editandoId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
    } else {
      await fetch("/api/obras", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
    }
    cancelarForm();
    setSaving(false);
    loadData();
  }

  async function excluirObra(id: string) {
    await fetch(`/api/obras/${id}`, { method: "DELETE" });
    setConfirmDelete(null);
    loadData();
  }

  // Função adicionada para gerar o link do portal
  async function gerarLinkPortal(obra: Obra) {
    const res = await fetch(`/api/obras/${obra.id}/portal`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ativo: true,
        titulo: `Reforma — ${obra.cliente?.nome}`,
      }),
    });
    const data = await res.json();
    if (data.token) {
      const url = `${window.location.origin}/portal/${data.token}`;
      navigator.clipboard.writeText(url);
      setLinkGerado(url);
      setTimeout(() => setLinkGerado(null), 4000);
    }
  }

  async function gerarPDF(obra: Obra) {
    setGerandoPDF(obra.id);
    try {
      const [matRes, pagRes, gastosRes, lancRes] = await Promise.all([
        fetch(`/api/materiais?obraId=${obra.id}`),
        fetch(`/api/pagamentos?obraId=${obra.id}`),
        fetch(`/api/gastos?obraId=${obra.id}`),
        fetch(`/api/lancamentos?obraId=${obra.id}`),
      ]);
      await gerarRelatorioPDF(
        obra,
        Array.isArray(await matRes.json())
          ? await (await fetch(`/api/materiais?obraId=${obra.id}`)).json()
          : [],
        Array.isArray(await pagRes.json())
          ? await (await fetch(`/api/pagamentos?obraId=${obra.id}`)).json()
          : [],
        Array.isArray(await gastosRes.json())
          ? await (await fetch(`/api/gastos?obraId=${obra.id}`)).json()
          : [],
        Array.isArray(await lancRes.json())
          ? await (await fetch(`/api/lancamentos?obraId=${obra.id}`)).json()
          : [],
      );
    } finally {
      setGerandoPDF(null);
    }
  }

  function margem(obra: Obra) {
    const gasto = obra.gastoMat + obra.gastoMO + obra.gastoEsporadico;
    return obra.contrato > 0
      ? Number((((obra.contrato - gasto) / obra.contrato) * 100).toFixed(0))
      : 0;
  }

  if (loading)
    return <div style={{ color: "var(--text-muted)" }}>Carregando...</div>;

  return (
    <div>
      {/* Modal excluir */}
      {confirmDelete && (
        <div style={S.modal}>
          <div style={{ ...S.modalBox, width: "360px" }}>
            <div style={{ fontSize: "20px", marginBottom: "8px" }}>🗑️</div>
            <h3
              style={{
                fontSize: "15px",
                fontWeight: 600,
                marginBottom: "8px",
                color: "var(--text-primary)",
              }}
            >
              Excluir obra?
            </h3>
            <p
              style={{
                fontSize: "13px",
                color: "var(--text-secondary)",
                marginBottom: "20px",
              }}
            >
              Esta ação não pode ser desfeita.
            </p>
            <div style={{ display: "flex", gap: "10px" }}>
              <button
                onClick={() => excluirObra(confirmDelete)}
                style={{
                  background: "var(--red)",
                  color: "#fff",
                  border: "none",
                  borderRadius: "8px",
                  padding: "9px 20px",
                  fontSize: "13px",
                  fontWeight: 600,
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                Sim, excluir
              </button>
              <button
                onClick={() => setConfirmDelete(null)}
                style={S.btnSecondary}
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Topo */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "16px",
        }}
      >
        <p style={{ fontSize: "13px", color: "var(--text-secondary)" }}>
          {obras.length} obra(s) cadastrada(s)
        </p>
        <button
          onClick={() => {
            cancelarForm();
            setShowForm(!showForm);
          }}
          style={{
            ...S.btnPrimary,
            background: showForm ? "var(--text-muted)" : "var(--blue)",
          }}
        >
          {showForm ? "Cancelar" : "+ Nova Obra"}
        </button>
      </div>

      {/* Formulário */}
      {showForm && (
        <div style={{ ...S.card, marginBottom: "16px" }}>
          <h3
            style={{
              fontSize: "14px",
              fontWeight: 600,
              marginBottom: "16px",
              color: "var(--text-primary)",
            }}
          >
            {editandoId ? "✏️ Editar Obra" : "Cadastrar Nova Obra"}
          </h3>
          <form onSubmit={handleSubmit}>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: "12px",
              }}
            >
              <div>
                <label style={S.label}>Centro de Custo</label>
                <input
                  name="centroCusto"
                  value={form.centroCusto}
                  onChange={handleChange}
                  required
                  placeholder="Ex: CC-002"
                  disabled={!!editandoId}
                  style={{
                    ...S.input,
                    background: editandoId
                      ? "var(--bg-tertiary)"
                      : "var(--bg-primary)",
                    opacity: editandoId ? 0.7 : 1,
                  }}
                />
              </div>
              <div>
                <label style={S.label}>Cliente</label>
                <div style={{ display: "flex", gap: "8px" }}>
                  <select
                    name="clienteId"
                    value={form.clienteId}
                    onChange={handleChange}
                    required
                    style={{ ...S.input, flex: 1 }}
                  >
                    <option value="">Selecione...</option>
                    {clientes.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.nome}
                      </option>
                    ))}
                  </select>
                  <button
                    type="button"
                    onClick={() => window.open("/clientes?novo=1", "_blank")}
                    title="Cadastrar novo cliente"
                    style={{
                      background: "var(--blue)",
                      color: "#fff",
                      border: "none",
                      borderRadius: "8px",
                      padding: "0 14px",
                      fontSize: "18px",
                      cursor: "pointer",
                      fontWeight: 700,
                      flexShrink: 0,
                    }}
                  >
                    +
                  </button>
                </div>
              </div>
              <div>
                <label style={S.label}>Tipo</label>
                <select
                  name="tipo"
                  value={form.tipo}
                  onChange={handleChange}
                  style={S.input}
                >
                  {TIPOS.map((t) => (
                    <option key={t} value={t}>
                      {t}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label style={S.label}>Status</label>
                <select
                  name="status"
                  value={form.status}
                  onChange={handleChange}
                  style={S.input}
                >
                  {STATUS.map((s) => (
                    <option key={s} value={s}>
                      {s}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label style={S.label}>Data de Início</label>
                <input
                  name="inicio"
                  type="date"
                  value={form.inicio}
                  onChange={handleChange}
                  required
                  style={S.input}
                />
              </div>
              <div>
                <label style={S.label}>Previsão de Entrega</label>
                <input
                  name="previsaoFim"
                  type="date"
                  value={form.previsaoFim}
                  onChange={handleChange}
                  required
                  style={S.input}
                />
              </div>
              <div>
                <label style={S.label}>Valor do Contrato (R$)</label>
                <input
                  name="contrato"
                  type="number"
                  value={form.contrato}
                  onChange={handleChange}
                  required
                  placeholder="0,00"
                  style={S.input}
                />
              </div>
              <div>
                <label style={S.label}>Orçamento Materiais (R$)</label>
                <input
                  name="orcamentoMat"
                  type="number"
                  value={form.orcamentoMat}
                  onChange={handleChange}
                  required
                  placeholder="0,00"
                  style={S.input}
                />
              </div>
              <div>
                <label style={S.label}>Orçamento Mão de Obra (R$)</label>
                <input
                  name="orcamentoMO"
                  type="number"
                  value={form.orcamentoMO}
                  onChange={handleChange}
                  required
                  placeholder="0,00"
                  style={S.input}
                />
              </div>
            </div>
            <div style={{ display: "flex", gap: "10px", marginTop: "16px" }}>
              <button
                type="submit"
                disabled={saving}
                style={{ ...S.btnPrimary, opacity: saving ? 0.6 : 1 }}
              >
                {saving
                  ? "Salvando..."
                  : editandoId
                    ? "Salvar alterações"
                    : "Salvar Obra"}
              </button>
              <button
                type="button"
                onClick={cancelarForm}
                style={S.btnSecondary}
              >
                Cancelar
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Tabela */}
      <div style={S.card}>
        <h3 style={S.cardTitle}>Todas as Obras</h3>
        {obras.length === 0 ? (
          <p style={{ fontSize: "13px", color: "var(--text-muted)" }}>
            Nenhuma obra cadastrada.
          </p>
        ) : (
          <table style={S.table}>
            <thead>
              <tr>
                {[
                  "CC",
                  "Cliente",
                  "Tipo",
                  "Contrato",
                  "Gasto",
                  "Margem",
                  "Status",
                  "Entrega",
                  "Ações",
                ].map((h) => (
                  <th key={h} style={S.th}>
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {obras.map((obra) => {
                const mg = margem(obra);
                const mgColor =
                  mg >= 35
                    ? "var(--green)"
                    : mg >= 20
                      ? "var(--amber)"
                      : "var(--red)";
                const gasto =
                  obra.gastoMat + obra.gastoMO + obra.gastoEsporadico;
                const tipoStyle = TIPO_COLORS[obra.tipo] || {
                  bg: "var(--bg-tertiary)",
                  color: "var(--text-secondary)",
                };
                const statusStyle = STATUS_COLORS[obra.status] || {
                  bg: "var(--bg-tertiary)",
                  color: "var(--text-secondary)",
                };
                return (
                  <tr key={obra.id}>
                    <td style={{ ...S.td, fontWeight: 600 }}>
                      {obra.centroCusto}
                    </td>
                    <td style={S.td}>{obra.cliente?.nome}</td>
                    <td style={S.td}>
                      <Badge label={obra.tipo} {...tipoStyle} />
                    </td>
                    <td style={S.td}>{formatMoney(obra.contrato)}</td>
                    <td style={{ ...S.td, color: "var(--red)" }}>
                      {formatMoney(gasto)}
                    </td>
                    <td style={{ ...S.td, fontWeight: 700, color: mgColor }}>
                      {mg}%
                    </td>
                    <td style={S.td}>
                      <Badge label={obra.status} {...statusStyle} />
                    </td>
                    <td style={{ ...S.td, color: "var(--text-secondary)" }}>
                      {new Date(obra.previsaoFim).toLocaleDateString("pt-BR")}
                    </td>
                    <td style={S.td}>
                      <div
                        style={{
                          display: "flex",
                          gap: "5px",
                          flexWrap: "wrap",
                        }}
                      >
                        <button
                          onClick={() =>
                            router.push(`/obras/${obra.id}/cronograma`)
                          }
                          style={{
                            background: "#E6F1FB",
                            color: "#0C447C",
                            border: "none",
                            borderRadius: "6px",
                            padding: "4px 9px",
                            fontSize: "11px",
                            fontWeight: 600,
                            cursor: "pointer",
                            fontFamily: "inherit",
                          }}
                        >
                          📊 Gantt
                        </button>

                        {/* Botão Portal adicionado aqui */}
                        <button
                          onClick={() => gerarLinkPortal(obra)}
                          style={{
                            background: "#EEEDFE",
                            color: "#3C3489",
                            border: "none",
                            borderRadius: "6px",
                            padding: "4px 9px",
                            fontSize: "11px",
                            fontWeight: 600,
                            cursor: "pointer",
                            fontFamily: "inherit",
                          }}
                        >
                          🔗 Portal
                        </button>

                        <button
                          onClick={() => abrirEdicao(obra)}
                          style={{
                            background: "#FAEEDA",
                            color: "#633806",
                            border: "none",
                            borderRadius: "6px",
                            padding: "4px 9px",
                            fontSize: "11px",
                            fontWeight: 600,
                            cursor: "pointer",
                            fontFamily: "inherit",
                          }}
                        >
                          ✏️ Editar
                        </button>
                        <button
                          onClick={() => gerarPDF(obra)}
                          disabled={gerandoPDF === obra.id}
                          style={{
                            background: "#EAF3DE",
                            color: "#27500A",
                            border: "none",
                            borderRadius: "6px",
                            padding: "4px 9px",
                            fontSize: "11px",
                            fontWeight: 600,
                            cursor: "pointer",
                            fontFamily: "inherit",
                            opacity: gerandoPDF === obra.id ? 0.6 : 1,
                          }}
                        >
                          {gerandoPDF === obra.id ? "⏳" : "📄 PDF"}
                        </button>
                        <button
                          onClick={() => setConfirmDelete(obra.id)}
                          style={{
                            background: "#FCEBEB",
                            color: "#791F1F",
                            border: "none",
                            borderRadius: "6px",
                            padding: "4px 9px",
                            fontSize: "11px",
                            fontWeight: 600,
                            cursor: "pointer",
                            fontFamily: "inherit",
                          }}
                        >
                          🗑️
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {/* Toast de confirmação adicionado antes do </div> final */}
      {linkGerado && (
        <div
          style={{
            position: "fixed",
            bottom: "24px",
            right: "24px",
            background: "#1D9E75",
            color: "#fff",
            padding: "12px 18px",
            borderRadius: "10px",
            fontSize: "13px",
            fontWeight: 500,
            boxShadow: "0 8px 24px rgba(0,0,0,0.2)",
            zIndex: 9999,
          }}
        >
          ✅ Link copiado! Cole no WhatsApp do cliente.
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

interface Cliente {
  id: string;
  nome: string;
}
interface Orcamento {
  id: string;
  numero: string;
  valor: number;
  status: string;
  linkArquivo?: string;
  observacoes?: string;
  cliente: Cliente;
  createdAt: string;
}

const STATUS_LIST = [
  "enviado",
  "negociacao",
  "aprovado",
  "recusado",
  "expirado",
];

const STATUS_STYLE: Record<
  string,
  { bg: string; color: string; label: string }
> = {
  enviado: { bg: "#E6F1FB", color: "#0C447C", label: "Enviado" },
  negociacao: { bg: "#FAEEDA", color: "#633806", label: "Negociação" },
  aprovado: { bg: "#EAF3DE", color: "#27500A", label: "Aprovado" },
  recusado: { bg: "#FCEBEB", color: "#791F1F", label: "Recusado" },
  expirado: { bg: "#F1EFE8", color: "#555", label: "Expirado" },
};

const TIPOS = ["residencial", "comercial", "industrial"];

function formatMoney(v: number) {
  return v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

const lbl: React.CSSProperties = {
  fontSize: "12px",
  color: "#666",
  display: "block",
  marginBottom: "5px",
};
const inp: React.CSSProperties = {
  width: "100%",
  border: "1px solid #e0e0e0",
  borderRadius: "8px",
  padding: "8px 10px",
  fontSize: "13px",
  fontFamily: "inherit",
  background: "#fff",
  outline: "none",
};

export default function OrcamentosPage() {
  const router = useRouter();
  const [orcamentos, setOrcamentos] = useState<Orcamento[]>([]);
  const [clientes, setClientes] = useState<Cliente[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [filtroStatus, setFiltroStatus] = useState("todos");
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [convertendo, setConvertendo] = useState<Orcamento | null>(null);
  const [erroConversao, setErroConversao] = useState("");

  const [form, setForm] = useState({
    numero: "",
    clienteId: "",
    valor: "",
    status: "enviado",
    linkArquivo: "",
    observacoes: "",
  });

  const [formConversao, setFormConversao] = useState({
    centroCusto: "",
    tipo: "residencial",
    inicio: "",
    previsaoFim: "",
    orcamentoMat: "",
    orcamentoMO: "",
  });

  async function loadData() {
    const [oRes, cRes] = await Promise.all([
      fetch("/api/orcamentos"),
      fetch("/api/clientes"),
    ]);
    const oData = await oRes.json();
    const cData = await cRes.json();
    setOrcamentos(Array.isArray(oData) ? oData : []);
    setClientes(Array.isArray(cData) ? cData : []);
    setLoading(false);
  }

  useEffect(() => {
    async function loadInitialData() {
      await loadData();
    }
    loadInitialData();
  }, []);

  function handleChange(
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  }

  function abrirEdicao(orc: Orcamento) {
    setEditandoId(orc.id);
    setForm({
      numero: orc.numero,
      clienteId: orc.cliente?.id || "",
      valor: String(orc.valor),
      status: orc.status,
      linkArquivo: orc.linkArquivo || "",
      observacoes: orc.observacoes || "",
    });
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function cancelarForm() {
    setShowForm(false);
    setEditandoId(null);
    setForm({
      numero: "",
      clienteId: "",
      valor: "",
      status: "enviado",
      linkArquivo: "",
      observacoes: "",
    });
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);

    if (editandoId) {
      await fetch(`/api/orcamentos/${editandoId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...form, valor: Number(form.valor) }),
      });
    } else {
      await fetch("/api/orcamentos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...form, valor: Number(form.valor) }),
      });
    }

    cancelarForm();
    setSaving(false);
    loadData();
  }

  async function excluirOrcamento(id: string) {
    await fetch(`/api/orcamentos/${id}`, { method: "DELETE" });
    setConfirmDelete(null);
    loadData();
  }

  async function atualizarStatus(id: string, status: string) {
    await fetch(`/api/orcamentos/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status }),
    });
    loadData();
  }

  function abrirConversao(orc: Orcamento) {
    setErroConversao("");
    setFormConversao({
      centroCusto: "",
      tipo: "residencial",
      inicio: "",
      previsaoFim: "",
      orcamentoMat: "",
      orcamentoMO: "",
    });
    setConvertendo(orc);
  }

  async function handleConverter(e: React.FormEvent) {
    e.preventDefault();
    if (!convertendo) return;
    setSaving(true);
    setErroConversao("");

    const res = await fetch(`/api/orcamentos/${convertendo.id}/converter`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(formConversao),
    });

    const data = await res.json();
    if (!res.ok) {
      setErroConversao(data.error || "Erro ao converter");
      setSaving(false);
      return;
    }

    setConvertendo(null);
    setSaving(false);
    loadData();
    router.push("/obras");
  }

  const porStatus = STATUS_LIST.reduce(
    (acc, s) => {
      acc[s] = orcamentos.filter((o) => o.status === s);
      return acc;
    },
    {} as Record<string, Orcamento[]>,
  );

  const taxaConversao =
    orcamentos.length > 0
      ? Math.round(
          ((porStatus.aprovado?.length || 0) / orcamentos.length) * 100,
        )
      : 0;

  const filtrados =
    filtroStatus === "todos"
      ? orcamentos
      : orcamentos.filter((o) => o.status === filtroStatus);

  if (loading) return <div style={{ color: "#888" }}>Carregando...</div>;

  return (
    <div>
      {/* Modal converter em obra */}
      {convertendo && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.45)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999,
          }}
        >
          <div
            style={{
              background: "#fff",
              borderRadius: "12px",
              padding: "28px 32px",
              width: "480px",
              boxShadow: "0 8px 32px rgba(0,0,0,0.18)",
            }}
          >
            <h3
              style={{ fontSize: "16px", fontWeight: 700, marginBottom: "4px" }}
            >
              🏗️ Converter em Obra
            </h3>
            <p
              style={{ fontSize: "13px", color: "#888", marginBottom: "20px" }}
            >
              Orçamento <strong>{convertendo.numero}</strong> —{" "}
              {convertendo.cliente?.nome} —{" "}
              <strong style={{ color: "#185FA5" }}>
                {formatMoney(convertendo.valor)}
              </strong>
            </p>
            {erroConversao && (
              <div
                style={{
                  background: "#FCEBEB",
                  border: "1px solid #f5c6c6",
                  borderRadius: "8px",
                  padding: "9px 12px",
                  fontSize: "12px",
                  color: "#791F1F",
                  marginBottom: "14px",
                }}
              >
                ⚠ {erroConversao}
              </div>
            )}
            <form onSubmit={handleConverter}>
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: "12px",
                }}
              >
                <div>
                  <label style={lbl}>Centro de Custo</label>
                  <input
                    value={formConversao.centroCusto}
                    onChange={(e) =>
                      setFormConversao((p) => ({
                        ...p,
                        centroCusto: e.target.value,
                      }))
                    }
                    required
                    placeholder="Ex: CC-002"
                    style={inp}
                  />
                </div>
                <div>
                  <label style={lbl}>Tipo</label>
                  <select
                    value={formConversao.tipo}
                    onChange={(e) =>
                      setFormConversao((p) => ({ ...p, tipo: e.target.value }))
                    }
                    style={inp}
                  >
                    {TIPOS.map((t) => (
                      <option key={t} value={t}>
                        {t}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label style={lbl}>Data de início</label>
                  <input
                    type="date"
                    value={formConversao.inicio}
                    onChange={(e) =>
                      setFormConversao((p) => ({
                        ...p,
                        inicio: e.target.value,
                      }))
                    }
                    required
                    style={inp}
                  />
                </div>
                <div>
                  <label style={lbl}>Previsão de entrega</label>
                  <input
                    type="date"
                    value={formConversao.previsaoFim}
                    onChange={(e) =>
                      setFormConversao((p) => ({
                        ...p,
                        previsaoFim: e.target.value,
                      }))
                    }
                    required
                    style={inp}
                  />
                </div>
                <div>
                  <label style={lbl}>Orçamento Materiais (R$)</label>
                  <input
                    type="number"
                    value={formConversao.orcamentoMat}
                    onChange={(e) =>
                      setFormConversao((p) => ({
                        ...p,
                        orcamentoMat: e.target.value,
                      }))
                    }
                    required
                    placeholder="0,00"
                    style={inp}
                  />
                </div>
                <div>
                  <label style={lbl}>Orçamento Mão de Obra (R$)</label>
                  <input
                    type="number"
                    value={formConversao.orcamentoMO}
                    onChange={(e) =>
                      setFormConversao((p) => ({
                        ...p,
                        orcamentoMO: e.target.value,
                      }))
                    }
                    required
                    placeholder="0,00"
                    style={inp}
                  />
                </div>
              </div>
              <div style={{ display: "flex", gap: "10px", marginTop: "18px" }}>
                <button
                  type="submit"
                  disabled={saving}
                  style={{
                    background: saving ? "#93c0e8" : "#185FA5",
                    color: "#fff",
                    border: "none",
                    borderRadius: "8px",
                    padding: "10px 20px",
                    fontSize: "13px",
                    fontWeight: 600,
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  {saving ? "Criando obra..." : "✅ Criar obra"}
                </button>
                <button
                  type="button"
                  onClick={() => setConvertendo(null)}
                  style={{
                    background: "#f5f5f3",
                    color: "#666",
                    border: "1px solid #e0e0e0",
                    borderRadius: "8px",
                    padding: "10px 20px",
                    fontSize: "13px",
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  Cancelar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal excluir */}
      {confirmDelete && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.4)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999,
          }}
        >
          <div
            style={{
              background: "#fff",
              borderRadius: "12px",
              padding: "28px 32px",
              width: "360px",
              boxShadow: "0 8px 32px rgba(0,0,0,0.15)",
            }}
          >
            <div style={{ fontSize: "20px", marginBottom: "8px" }}>🗑️</div>
            <h3
              style={{ fontSize: "15px", fontWeight: 600, marginBottom: "8px" }}
            >
              Excluir orçamento?
            </h3>
            <p
              style={{ fontSize: "13px", color: "#888", marginBottom: "20px" }}
            >
              Esta ação não pode ser desfeita.
            </p>
            <div style={{ display: "flex", gap: "10px" }}>
              <button
                onClick={() => excluirOrcamento(confirmDelete)}
                style={{
                  background: "#E24B4A",
                  color: "#fff",
                  border: "none",
                  borderRadius: "8px",
                  padding: "9px 20px",
                  fontSize: "13px",
                  fontWeight: 600,
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                Sim, excluir
              </button>
              <button
                onClick={() => setConfirmDelete(null)}
                style={{
                  background: "#f5f5f3",
                  color: "#666",
                  border: "1px solid #e0e0e0",
                  borderRadius: "8px",
                  padding: "9px 20px",
                  fontSize: "13px",
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Métricas */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(5,1fr)",
          gap: "10px",
          marginBottom: "16px",
        }}
      >
        {STATUS_LIST.map((s) => {
          const st = STATUS_STYLE[s];
          const itens = porStatus[s] || [];
          return (
            <div
              key={s}
              style={{
                background: "#fff",
                border: "1px solid #e0e0e0",
                borderRadius: "10px",
                padding: "12px 14px",
              }}
            >
              <div
                style={{
                  fontSize: "10px",
                  color: "#888",
                  marginBottom: "4px",
                  textTransform: "uppercase",
                  letterSpacing: "0.04em",
                }}
              >
                {st.label}
              </div>
              <div
                style={{ fontSize: "20px", fontWeight: 700, color: st.color }}
              >
                {itens.length}
              </div>
              <div
                style={{ fontSize: "11px", color: "#aaa", marginTop: "2px" }}
              >
                {formatMoney(itens.reduce((a, o) => a + o.valor, 0))}
              </div>
            </div>
          );
        })}
      </div>

      {/* Pipeline visual */}
      <div
        style={{
          background: "#fff",
          border: "1px solid #e0e0e0",
          borderRadius: "10px",
          padding: "16px 20px",
          marginBottom: "14px",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            marginBottom: "12px",
          }}
        >
          <h3
            style={{
              fontSize: "11px",
              fontWeight: 600,
              color: "#888",
              textTransform: "uppercase",
              letterSpacing: "0.05em",
            }}
          >
            Pipeline de orçamentos
          </h3>
          <span style={{ fontSize: "12px", color: "#888" }}>
            Taxa de conversão:{" "}
            <strong style={{ color: "#1D9E75" }}>{taxaConversao}%</strong>
          </span>
        </div>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(5,1fr)",
            gap: "8px",
          }}
        >
          {STATUS_LIST.map((s) => {
            const st = STATUS_STYLE[s];
            const itens = porStatus[s] || [];
            return (
              <div
                key={s}
                style={{
                  background: "#f8f8f6",
                  borderRadius: "8px",
                  padding: "10px",
                }}
              >
                <div
                  style={{
                    fontSize: "10px",
                    fontWeight: 600,
                    color: "#888",
                    textTransform: "uppercase",
                    letterSpacing: "0.04em",
                    marginBottom: "8px",
                  }}
                >
                  {st.label}
                </div>
                {itens.length === 0 ? (
                  <div
                    style={{
                      fontSize: "11px",
                      color: "#ccc",
                      textAlign: "center",
                      padding: "10px 0",
                    }}
                  >
                    vazio
                  </div>
                ) : (
                  itens.map((o) => (
                    <div
                      key={o.id}
                      style={{
                        background: "#fff",
                        border: "1px solid #e0e0e0",
                        borderRadius: "6px",
                        padding: "8px",
                        marginBottom: "6px",
                      }}
                    >
                      <div
                        style={{
                          fontSize: "11px",
                          fontWeight: 600,
                          marginBottom: "2px",
                          overflow: "hidden",
                          textOverflow: "ellipsis",
                          whiteSpace: "nowrap",
                        }}
                      >
                        {o.cliente?.nome}
                      </div>
                      <div
                        style={{
                          fontSize: "12px",
                          color: "#185FA5",
                          fontWeight: 600,
                        }}
                      >
                        {formatMoney(o.valor)}
                      </div>
                      <div
                        style={{
                          fontSize: "10px",
                          color: "#aaa",
                          marginTop: "2px",
                        }}
                      >
                        {o.numero}
                      </div>
                      {o.status === "aprovado" && (
                        <button
                          onClick={() => abrirConversao(o)}
                          style={{
                            marginTop: "6px",
                            width: "100%",
                            background: "#185FA5",
                            color: "#fff",
                            border: "none",
                            borderRadius: "5px",
                            padding: "4px 0",
                            fontSize: "10px",
                            fontWeight: 600,
                            cursor: "pointer",
                            fontFamily: "inherit",
                          }}
                        >
                          🏗️ Converter em Obra
                        </button>
                      )}
                    </div>
                  ))
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Filtros + botão */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "12px",
        }}
      >
        <div style={{ display: "flex", gap: "6px", flexWrap: "wrap" }}>
          {["todos", ...STATUS_LIST].map((s) => (
            <button
              key={s}
              onClick={() => setFiltroStatus(s)}
              style={{
                border: "1px solid #e0e0e0",
                borderRadius: "20px",
                padding: "4px 12px",
                fontSize: "12px",
                cursor: "pointer",
                fontFamily: "inherit",
                background: filtroStatus === s ? "#185FA5" : "#fff",
                color: filtroStatus === s ? "#fff" : "#555",
                fontWeight: filtroStatus === s ? 600 : 400,
              }}
            >
              {s === "todos" ? "Todos" : STATUS_STYLE[s].label}
            </button>
          ))}
        </div>
        <button
          onClick={() => {
            cancelarForm();
            setShowForm(!showForm);
          }}
          style={{
            background: showForm ? "#888" : "#185FA5",
            color: "#fff",
            border: "none",
            borderRadius: "8px",
            padding: "9px 16px",
            fontSize: "13px",
            fontWeight: 600,
            cursor: "pointer",
            fontFamily: "inherit",
          }}
        >
          {showForm ? "Cancelar" : "+ Novo Orçamento"}
        </button>
      </div>

      {/* Formulário */}
      {showForm && (
        <div
          style={{
            background: "#fff",
            border: "1px solid #e0e0e0",
            borderRadius: "10px",
            padding: "20px",
            marginBottom: "16px",
          }}
        >
          <h3
            style={{ fontSize: "14px", fontWeight: 600, marginBottom: "16px" }}
          >
            {editandoId ? "✏️ Editar Orçamento" : "Cadastrar Orçamento"}
          </h3>
          <form onSubmit={handleSubmit}>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: "12px",
              }}
            >
              <div>
                <label style={lbl}>Número do orçamento</label>
                <input
                  name="numero"
                  value={form.numero}
                  onChange={handleChange}
                  required
                  placeholder="Ex: 0180/2025"
                  disabled={!!editandoId}
                  style={{
                    ...inp,
                    background: editandoId ? "#f5f5f3" : "#fff",
                  }}
                />
              </div>
              <div>
                <label style={lbl}>Cliente</label>
                <select
                  name="clienteId"
                  value={form.clienteId}
                  onChange={handleChange}
                  required
                  style={inp}
                >
                  <option value="">Selecione...</option>
                  {clientes.map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.nome}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label style={lbl}>Valor (R$)</label>
                <input
                  name="valor"
                  type="number"
                  value={form.valor}
                  onChange={handleChange}
                  required
                  placeholder="0,00"
                  style={inp}
                />
              </div>
              <div>
                <label style={lbl}>Status</label>
                <select
                  name="status"
                  value={form.status}
                  onChange={handleChange}
                  style={inp}
                >
                  {STATUS_LIST.map((s) => (
                    <option key={s} value={s}>
                      {STATUS_STYLE[s].label}
                    </option>
                  ))}
                </select>
              </div>
              <div style={{ gridColumn: "1/-1" }}>
                <label style={lbl}>
                  Link do arquivo (OneDrive / Google Drive)
                </label>
                <input
                  name="linkArquivo"
                  value={form.linkArquivo}
                  onChange={handleChange}
                  placeholder="https://onedrive.live.com/..."
                  style={inp}
                />
              </div>
              <div style={{ gridColumn: "1/-1" }}>
                <label style={lbl}>Observações</label>
                <input
                  name="observacoes"
                  value={form.observacoes}
                  onChange={handleChange}
                  placeholder="Ex: Cliente pediu desconto de 10%..."
                  style={inp}
                />
              </div>
            </div>
            <div style={{ display: "flex", gap: "10px", marginTop: "16px" }}>
              <button
                type="submit"
                disabled={saving}
                style={{
                  background: saving ? "#93c0e8" : "#185FA5",
                  color: "#fff",
                  border: "none",
                  borderRadius: "8px",
                  padding: "10px 20px",
                  fontSize: "13px",
                  fontWeight: 600,
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                {saving
                  ? "Salvando..."
                  : editandoId
                    ? "Salvar alterações"
                    : "Salvar Orçamento"}
              </button>
              <button
                type="button"
                onClick={cancelarForm}
                style={{
                  background: "#f5f5f3",
                  color: "#666",
                  border: "1px solid #e0e0e0",
                  borderRadius: "8px",
                  padding: "10px 20px",
                  fontSize: "13px",
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                Cancelar
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Tabela */}
      <div
        style={{
          background: "#fff",
          border: "1px solid #e0e0e0",
          borderRadius: "10px",
          padding: "18px 20px",
        }}
      >
        <h3
          style={{
            fontSize: "11px",
            fontWeight: 600,
            color: "#888",
            textTransform: "uppercase",
            letterSpacing: "0.05em",
            marginBottom: "14px",
          }}
        >
          Todos os orçamentos{" "}
          {filtroStatus !== "todos" && `— ${STATUS_STYLE[filtroStatus]?.label}`}
        </h3>
        {filtrados.length === 0 ? (
          <p style={{ fontSize: "13px", color: "#aaa" }}>
            Nenhum orçamento encontrado.
          </p>
        ) : (
          <table
            style={{
              width: "100%",
              borderCollapse: "collapse",
              fontSize: "13px",
            }}
          >
            <thead>
              <tr>
                {[
                  "Número",
                  "Cliente",
                  "Valor",
                  "Status",
                  "Observações",
                  "Arquivo",
                  "Ações",
                ].map((h) => (
                  <th
                    key={h}
                    style={{
                      textAlign: "left",
                      padding: "0 0 10px 0",
                      fontSize: "11px",
                      fontWeight: 600,
                      color: "#888",
                      borderBottom: "1px solid #e0e0e0",
                    }}
                  >
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtrados.map((o) => {
                const st = STATUS_STYLE[o.status] || STATUS_STYLE.enviado;
                return (
                  <tr key={o.id}>
                    <td
                      style={{
                        padding: "10px 0",
                        borderBottom: "1px solid #f0f0f0",
                        fontWeight: 600,
                      }}
                    >
                      {o.numero}
                    </td>
                    <td
                      style={{
                        padding: "10px 0",
                        borderBottom: "1px solid #f0f0f0",
                        color: "#555",
                      }}
                    >
                      {o.cliente?.nome}
                    </td>
                    <td
                      style={{
                        padding: "10px 0",
                        borderBottom: "1px solid #f0f0f0",
                        fontWeight: 600,
                        color: "#185FA5",
                      }}
                    >
                      {formatMoney(o.valor)}
                    </td>
                    <td
                      style={{
                        padding: "10px 0",
                        borderBottom: "1px solid #f0f0f0",
                      }}
                    >
                      <span
                        style={{
                          background: st.bg,
                          color: st.color,
                          padding: "2px 8px",
                          borderRadius: "10px",
                          fontSize: "11px",
                          fontWeight: 600,
                        }}
                      >
                        {st.label}
                      </span>
                    </td>
                    <td
                      style={{
                        padding: "10px 0",
                        borderBottom: "1px solid #f0f0f0",
                        color: "#888",
                        fontSize: "12px",
                        maxWidth: "140px",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {o.observacoes || "—"}
                    </td>
                    <td
                      style={{
                        padding: "10px 0",
                        borderBottom: "1px solid #f0f0f0",
                      }}
                    >
                      {o.linkArquivo ? (
                        <a
                          href={o.linkArquivo}
                          target="_blank"
                          rel="noreferrer"
                          style={{
                            fontSize: "11px",
                            color: "#185FA5",
                            background: "#E6F1FB",
                            padding: "2px 8px",
                            borderRadius: "10px",
                            textDecoration: "none",
                            fontWeight: 600,
                          }}
                        >
                          Abrir ↗
                        </a>
                      ) : (
                        <span style={{ color: "#ccc" }}>—</span>
                      )}
                    </td>
                    <td
                      style={{
                        padding: "10px 0",
                        borderBottom: "1px solid #f0f0f0",
                      }}
                    >
                      <div
                        style={{
                          display: "flex",
                          gap: "5px",
                          flexWrap: "wrap",
                          alignItems: "center",
                        }}
                      >
                        {/* Mudar status */}
                        <select
                          defaultValue={o.status}
                          onChange={(e) =>
                            atualizarStatus(o.id, e.target.value)
                          }
                          style={{
                            border: "1px solid #e0e0e0",
                            borderRadius: "6px",
                            padding: "4px 6px",
                            fontSize: "11px",
                            fontFamily: "inherit",
                            cursor: "pointer",
                            background: "#fff",
                          }}
                        >
                          {STATUS_LIST.map((s) => (
                            <option key={s} value={s}>
                              {STATUS_STYLE[s].label}
                            </option>
                          ))}
                        </select>

                        {/* Editar */}
                        <button
                          onClick={() => abrirEdicao(o)}
                          style={{
                            background: "#FAEEDA",
                            color: "#633806",
                            border: "none",
                            borderRadius: "6px",
                            padding: "4px 8px",
                            fontSize: "11px",
                            fontWeight: 600,
                            cursor: "pointer",
                            fontFamily: "inherit",
                          }}
                        >
                          ✏️
                        </button>

                        {/* Excluir */}
                        <button
                          onClick={() => setConfirmDelete(o.id)}
                          style={{
                            background: "#FCEBEB",
                            color: "#791F1F",
                            border: "none",
                            borderRadius: "6px",
                            padding: "4px 8px",
                            fontSize: "11px",
                            fontWeight: 600,
                            cursor: "pointer",
                            fontFamily: "inherit",
                          }}
                        >
                          🗑️
                        </button>

                        {/* Converter */}
                        {o.status === "aprovado" && (
                          <button
                            onClick={() => abrirConversao(o)}
                            style={{
                              background: "#185FA5",
                              color: "#fff",
                              border: "none",
                              borderRadius: "6px",
                              padding: "4px 8px",
                              fontSize: "11px",
                              fontWeight: 600,
                              cursor: "pointer",
                              fontFamily: "inherit",
                              whiteSpace: "nowrap",
                            }}
                          >
                            🏗️
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import * as S from "@/lib/styles";

interface Obra {
  id: string;
  centroCusto: string;
  cliente: { nome: string };
}

interface MembroEquipe {
  nome: string;
  funcao: string;
  presente: boolean;
  horas: number;
}
interface Atividade {
  descricao: string;
  etapa: string;
  percentual: number;
  status: string;
}
interface RDOFoto {
  id: string;
  url: string;
  descricao?: string;
  etapa?: string;
}
interface RDO {
  id: string;
  data: string;
  clima: string;
  tempMax?: number;
  tempMin?: number;
  anotacoes?: string;
  ocorrencias?: string;
  obra: Obra;
  equipe: MembroEquipe[];
  atividades: Atividade[];
  fotos: RDOFoto[];
}

const CLIMAS = [
  { value: "ensolarado", label: "☀️ Ensolarado" },
  { value: "parcialmente_nublado", label: "⛅ Parcialmente nublado" },
  { value: "nublado", label: "☁️ Nublado" },
  { value: "chuvoso", label: "🌧️ Chuvoso" },
  { value: "tempestade", label: "⛈️ Tempestade" },
];

const FUNCOES = [
  "Pedreiro",
  "Pintor",
  "Eletricista",
  "Encanador",
  "Servente",
  "Gesseiro",
  "Azulejista",
  "Mestre de obras",
  "Engenheiro",
  "Outro",
];
const STATUS_ATIV = ["executado", "em_andamento", "pendente", "impedido"];
const STATUS_STYLE: Record<string, { bg: string; color: string }> = {
  executado: { bg: "#EAF3DE", color: "#27500A" },
  em_andamento: { bg: "#E6F1FB", color: "#0C447C" },
  pendente: { bg: "#FAEEDA", color: "#633806" },
  impedido: { bg: "#FCEBEB", color: "#791F1F" },
};

function formatDate(d: string) {
  return new Date(d).toLocaleDateString("pt-BR", {
    weekday: "long",
    day: "2-digit",
    month: "long",
    year: "numeric",
  });
}

export default function RDOPage() {
  const [rdos, setRdos] = useState<RDO[]>([]);
  const [obras, setObras] = useState<Obra[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [rdoAberto, setRdoAberto] = useState<string | null>(null);
  const [filtroObra, setFiltroObra] = useState("");
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);

  // Form state
  const [form, setForm] = useState({
    obraId: "",
    data: new Date().toISOString().slice(0, 10),
    clima: "ensolarado",
    tempMax: "",
    tempMin: "",
    anotacoes: "",
    ocorrencias: "",
  });
  const [equipe, setEquipe] = useState<MembroEquipe[]>([
    { nome: "", funcao: "Pedreiro", presente: true, horas: 8 },
  ]);
  const [atividades, setAtividades] = useState<Atividade[]>([
    { descricao: "", etapa: "", percentual: 0, status: "executado" },
  ]);

  async function loadData() {
    const [rRes, oRes] = await Promise.all([
      fetch("/api/rdo").then((r) => r.json()),
      fetch("/api/obras").then((r) => r.json()),
    ]);
    setRdos(Array.isArray(rRes) ? rRes : []);
    setObras(Array.isArray(oRes) ? oRes : []);
    setLoading(false);
  }

  useEffect(() => {
    async function init() {
      await loadData();
    }
    init();
  }, []);

  function addMembro() {
    setEquipe((p) => [
      ...p,
      { nome: "", funcao: "Pedreiro", presente: true, horas: 8 },
    ]);
  }
  function removeMembro(i: number) {
    setEquipe((p) => p.filter((_, idx) => idx !== i));
  }
  function updateMembro(
    i: number,
    field: string,
    value: string | number | boolean,
  ) {
    setEquipe((p) =>
      p.map((m, idx) => (idx === i ? { ...m, [field]: value } : m)),
    );
  }

  function addAtividade() {
    setAtividades((p) => [
      ...p,
      { descricao: "", etapa: "", percentual: 0, status: "executado" },
    ]);
  }
  function removeAtividade(i: number) {
    setAtividades((p) => p.filter((_, idx) => idx !== i));
  }
  function updateAtividade(
    i: number,
    field: string,
    value: string | number | boolean,
  ) {
    setAtividades((p) =>
      p.map((a, idx) => (idx === i ? { ...a, [field]: value } : a)),
    );
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    try {
      await fetch("/api/rdo", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...form,
          tempMax: form.tempMax ? Number(form.tempMax) : null,
          tempMin: form.tempMin ? Number(form.tempMin) : null,
          equipe: equipe.filter((m) => m.nome.trim()),
          atividades: atividades.filter((a) => a.descricao.trim()),
        }),
      });
      setForm({
        obraId: "",
        data: new Date().toISOString().slice(0, 10),
        clima: "ensolarado",
        tempMax: "",
        tempMin: "",
        anotacoes: "",
        ocorrencias: "",
      });
      setEquipe([{ nome: "", funcao: "Pedreiro", presente: true, horas: 8 }]);
      setAtividades([
        { descricao: "", etapa: "", percentual: 0, status: "executado" },
      ]);
      setShowForm(false);
      loadData();
    } finally {
      setSaving(false);
    }
  }

  async function excluir(id: string) {
    await fetch(`/api/rdo/${id}`, { method: "DELETE" });
    setConfirmDelete(null);
    loadData();
  }

  const rdosFiltrados = filtroObra
    ? rdos.filter((r) => r.obra?.id === filtroObra)
    : rdos;

  if (loading)
    return <div style={{ color: "var(--text-muted)" }}>Carregando...</div>;

  return (
    <div>
      {/* Modal excluir */}
      {confirmDelete && (
        <div style={S.modal}>
          <div style={{ ...S.modalBox, width: "360px" }}>
            <h3
              style={{
                fontSize: "15px",
                fontWeight: 600,
                marginBottom: "8px",
                color: "var(--text-primary)",
              }}
            >
              🗑️ Excluir RDO?
            </h3>
            <p
              style={{
                fontSize: "13px",
                color: "var(--text-secondary)",
                marginBottom: "20px",
              }}
            >
              Esta ação não pode ser desfeita.
            </p>
            <div style={{ display: "flex", gap: "10px" }}>
              <button
                onClick={() => excluir(confirmDelete)}
                style={{
                  background: "var(--red)",
                  color: "#fff",
                  border: "none",
                  borderRadius: "8px",
                  padding: "9px 20px",
                  fontSize: "13px",
                  fontWeight: 600,
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                Sim, excluir
              </button>
              <button
                onClick={() => setConfirmDelete(null)}
                style={S.btnSecondary}
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Topo */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "16px",
          flexWrap: "wrap",
          gap: "10px",
        }}
      >
        <div
          style={{
            display: "flex",
            gap: "8px",
            alignItems: "center",
            flexWrap: "wrap",
          }}
        >
          <p style={{ fontSize: "13px", color: "var(--text-secondary)" }}>
            {rdos.length} registro(s)
          </p>
          <select
            value={filtroObra}
            onChange={(e) => setFiltroObra(e.target.value)}
            style={{
              ...S.input,
              width: "auto",
              padding: "6px 10px",
              fontSize: "12px",
            }}
          >
            <option value="">Todas as obras</option>
            {obras.map((o) => (
              <option key={o.id} value={o.id}>
                {o.centroCusto} — {o.cliente?.nome}
              </option>
            ))}
          </select>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          style={{
            ...S.btnPrimary,
            background: showForm ? "var(--text-muted)" : "var(--blue)",
          }}
        >
          {showForm ? "Cancelar" : "📝 Novo RDO"}
        </button>
      </div>

      {/* Formulário */}
      {showForm && (
        <div style={{ ...S.card, marginBottom: "16px" }}>
          <h3
            style={{
              fontSize: "15px",
              fontWeight: 600,
              marginBottom: "20px",
              color: "var(--text-primary)",
            }}
          >
            📋 Registro Diário de Obra
          </h3>
          <form onSubmit={handleSubmit}>
            {/* Dados gerais */}
            <div style={{ marginBottom: "20px" }}>
              <div
                style={{
                  fontSize: "12px",
                  fontWeight: 600,
                  color: "var(--text-secondary)",
                  textTransform: "uppercase",
                  letterSpacing: "0.05em",
                  marginBottom: "12px",
                }}
              >
                Dados gerais
              </div>
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: "12px",
                }}
              >
                <div>
                  <label style={S.label}>Obra</label>
                  <select
                    value={form.obraId}
                    onChange={(e) =>
                      setForm((p) => ({ ...p, obraId: e.target.value }))
                    }
                    required
                    style={S.input}
                  >
                    <option value="">Selecione a obra...</option>
                    {obras.map((o) => (
                      <option key={o.id} value={o.id}>
                        {o.centroCusto} — {o.cliente?.nome}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label style={S.label}>Data</label>
                  <input
                    type="date"
                    value={form.data}
                    onChange={(e) =>
                      setForm((p) => ({ ...p, data: e.target.value }))
                    }
                    required
                    style={S.input}
                  />
                </div>
                <div>
                  <label style={S.label}>Clima</label>
                  <select
                    value={form.clima}
                    onChange={(e) =>
                      setForm((p) => ({ ...p, clima: e.target.value }))
                    }
                    style={S.input}
                  >
                    {CLIMAS.map((c) => (
                      <option key={c.value} value={c.value}>
                        {c.label}
                      </option>
                    ))}
                  </select>
                </div>
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "1fr 1fr",
                    gap: "8px",
                  }}
                >
                  <div>
                    <label style={S.label}>Temp. máx (°C)</label>
                    <input
                      type="number"
                      value={form.tempMax}
                      onChange={(e) =>
                        setForm((p) => ({ ...p, tempMax: e.target.value }))
                      }
                      placeholder="Ex: 34"
                      style={S.input}
                    />
                  </div>
                  <div>
                    <label style={S.label}>Temp. mín (°C)</label>
                    <input
                      type="number"
                      value={form.tempMin}
                      onChange={(e) =>
                        setForm((p) => ({ ...p, tempMin: e.target.value }))
                      }
                      placeholder="Ex: 24"
                      style={S.input}
                    />
                  </div>
                </div>
              </div>
            </div>

            {/* Equipe */}
            <div style={{ marginBottom: "20px" }}>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "12px",
                }}
              >
                <div
                  style={{
                    fontSize: "12px",
                    fontWeight: 600,
                    color: "var(--text-secondary)",
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  }}
                >
                  👷 Equipe no canteiro
                </div>
                <button
                  type="button"
                  onClick={addMembro}
                  style={{
                    ...S.btnSecondary,
                    fontSize: "12px",
                    padding: "4px 10px",
                  }}
                >
                  + Adicionar
                </button>
              </div>
              {equipe.map((m, i) => (
                <div
                  key={i}
                  style={{
                    display: "grid",
                    gridTemplateColumns: "2fr 1fr 80px 80px 36px",
                    gap: "8px",
                    marginBottom: "8px",
                    alignItems: "center",
                  }}
                >
                  <input
                    value={m.nome}
                    onChange={(e) => updateMembro(i, "nome", e.target.value)}
                    placeholder="Nome do trabalhador"
                    style={{ ...S.input, margin: 0 }}
                  />
                  <select
                    value={m.funcao}
                    onChange={(e) => updateMembro(i, "funcao", e.target.value)}
                    style={{ ...S.input, margin: 0 }}
                  >
                    {FUNCOES.map((f) => (
                      <option key={f} value={f}>
                        {f}
                      </option>
                    ))}
                  </select>
                  <input
                    type="number"
                    value={m.horas}
                    onChange={(e) =>
                      updateMembro(i, "horas", Number(e.target.value))
                    }
                    min="0"
                    max="24"
                    style={{ ...S.input, margin: 0 }}
                    title="Horas trabalhadas"
