import { NextRequest, NextResponse } from "next/server";
import { PrismaClient } from "@prisma/client";
import { withAuth } from "@/lib/authMiddleware";

const prisma = new PrismaClient();

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  return withAuth(request, async (_req, _tenantId, role) => {
    if (role !== "admin") {
      return NextResponse.json({ error: "Acesso negado" }, { status: 403 });
    }
    const { id } = await params;
    const { role: novoRole } = await request.json();
    if (!["admin", "user"].includes(novoRole)) {
      return NextResponse.json({ error: "Role inválido" }, { status: 400 });
    }
    const updated = await prisma.user.update({
      where: { id },
      data: { role: novoRole },
    });
    return NextResponse.json(updated);
  });
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  return withAuth(request, async (_req, tenantId, role) => {
    if (role !== "admin") {
      return NextResponse.json({ error: "Acesso negado" }, { status: 403 });
    }
    const { id } = await params;
    if (id === tenantId) {
      return NextResponse.json(
        { error: "Você não pode excluir sua própria conta" },
        { status: 400 },
      );
    }

    // Busca IDs das obras do usuário para cascata
    const obras = await prisma.obra.findMany({
      where: { tenantId: id },
      select: { id: true },
    });
    const obraIds = obras.map((o) => o.id);

    // Busca IDs dos RDOs do usuário
    const rdos = await prisma.rDO.findMany({
      where: { tenantId: id },
      select: { id: true },
    });
    const rdoIds = rdos.map((r) => r.id);

    // Deleta filhos dos RDOs
    await prisma.rDOEquipe.deleteMany({ where: { rdoId: { in: rdoIds } } });
    await prisma.rDOAtividade.deleteMany({ where: { rdoId: { in: rdoIds } } });
    await prisma.rDOFoto.deleteMany({ where: { rdoId: { in: rdoIds } } });
    await prisma.rDO.deleteMany({ where: { tenantId: id } });

    // Deleta filhos das obras
    await prisma.subtarefa.deleteMany({
      where: { etapa: { obraId: { in: obraIds } } },
    });
    await prisma.etapa.deleteMany({ where: { obraId: { in: obraIds } } });
    await prisma.pagamento.deleteMany({
      where: { diarista: { obraId: { in: obraIds } } },
    });
    await prisma.diarista.deleteMany({ where: { obraId: { in: obraIds } } });
    await prisma.ocorrencia.deleteMany({ where: { obraId: { in: obraIds } } });
    await prisma.material.deleteMany({ where: { tenantId: id } });
    await prisma.gastoEsporadico.deleteMany({ where: { tenantId: id } });
    await prisma.lancamento.deleteMany({ where: { tenantId: id } });
    await prisma.orcamento.deleteMany({ where: { tenantId: id } });
    await prisma.obra.deleteMany({ where: { tenantId: id } });
    await prisma.cliente.deleteMany({ where: { tenantId: id } });
    await prisma.fornecedor.deleteMany({ where: { tenantId: id } });
    await prisma.user.delete({ where: { id } });

    return NextResponse.json({ ok: true });
  });
}

import { NextRequest, NextResponse } from "next/server";
import { PrismaClient } from "@prisma/client";
import { withAuth } from "@/lib/authMiddleware";

const prisma = new PrismaClient();

export async function GET(request: NextRequest) {
  return withAuth(request, async (_req, _tenantId, role) => {
    if (role !== "admin") {
      return NextResponse.json({ error: "Acesso negado" }, { status: 403 });
    }

    // User não tem relação direta com Obra no schema —
    // a ligação é via tenantId, então buscamos a contagem separada
    const usuarios = await prisma.user.findMany({
      select: {
        id: true,
        name: true,
        email: true,
        empresa: true,
        role: true,
        createdAt: true,
      },
      orderBy: { createdAt: "desc" },
    });

    // Conta obras por tenantId (userId) para cada usuário
    const obrasCount = await prisma.obra.groupBy({
      by: ["tenantId"],
      _count: { id: true },
    });

    const countMap = Object.fromEntries(
      obrasCount.map((o) => [o.tenantId, o._count.id]),
    );

    const resultado = usuarios.map((u) => ({
      ...u,
      _count: { obras: countMap[u.id] ?? 0 },
    }));

    return NextResponse.json(resultado);
  });
}

import { NextRequest, NextResponse } from "next/server";
import { PrismaClient } from "@prisma/client";
import { hashPassword, generateToken } from "@/lib/auth";
import { z } from "zod";

const prisma = new PrismaClient();

const cadastroSchema = z.object({
  nome: z.string().min(2, "Nome muito curto"),
  empresa: z.string().min(2, "Nome da empresa muito curto"),
  email: z.string().email("E-mail inválido"),
  senha: z.string().min(6, "Senha deve ter ao menos 6 caracteres"),
});

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const result = cadastroSchema.safeParse(body);

    if (!result.success) {
      return NextResponse.json(
        { error: result.error.issues[0].message },
        { status: 400 },
      );
    }

    const { nome, empresa, email, senha } = result.data;

    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) {
      return NextResponse.json(
        { error: "Este e-mail já está cadastrado" },
        { status: 409 },
      );
    }

    const hashedPassword = await hashPassword(senha);

    const user = await prisma.user.create({
      data: {
        name: nome,
        email,
        password: hashedPassword,
        empresa,
        role: "user",
      },
    });

    const token = generateToken(user.id, user.email, user.role);

    const response = NextResponse.json({ ok: true });
    response.cookies.set("engetech-token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 60 * 60 * 24 * 7,
      path: "/",
    });

    return response;
  } catch (error) {
    console.error("[POST /api/auth/cadastro]", error);
    return NextResponse.json(
      { error: "Erro interno do servidor" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { verifyPassword, generateToken } from "@/lib/auth";

export async function POST(request: NextRequest) {
  try {
    const { email, password } = await request.json();

    if (!email || !password) {
      return NextResponse.json(
        { error: "Email e senha obrigatórios" },
        { status: 400 },
      );
    }

    const user = await prisma.user.findUnique({ where: { email } });

    if (!user) {
      return NextResponse.json(
        { error: "Usuário não encontrado" },
        { status: 401 },
      );
    }

    const isValid = await verifyPassword(password, user.password);

    if (!isValid) {
      return NextResponse.json({ error: "Senha incorreta" }, { status: 401 });
    }

    const token = generateToken(user.id, user.email, user.role);
    const isProduction = process.env.NODE_ENV === "production";

    const response = NextResponse.json({
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
      },
    });

    response.cookies.set({
      name: "engetech-token",
      value: token,
      httpOnly: true,
      secure: isProduction,
      sameSite: "lax",
      maxAge: 60 * 60 * 24 * 7,
      path: "/",
    });

    return response;
  } catch (error) {
    console.error("Erro no login:", error);
    return NextResponse.json(
      { error: "Erro interno do servidor" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";

export async function POST() {
  const response = NextResponse.json({ success: true });
  response.cookies.delete("engetech-token");
