"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  Building2,
  User,
  Mail,
  Lock,
  Eye,
  EyeOff,
  ArrowRight,
  CheckCircle2,
  HardHat,
} from "lucide-react";

export default function CadastroPage() {
  const router = useRouter();
  const [step, setStep] = useState(1);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [form, setForm] = useState({
    nome: "",
    empresa: "",
    email: "",
    senha: "",
    confirmarSenha: "",
  });

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
    setError("");
  }

  function validarStep1() {
    if (!form.nome.trim()) return "Informe seu nome completo";
    if (!form.empresa.trim()) return "Informe o nome da empresa";
    return null;
  }

  function validarStep2() {
    if (!form.email.trim() || !form.email.includes("@"))
      return "E-mail inválido";
    if (form.senha.length < 6) return "A senha deve ter ao menos 6 caracteres";
    if (form.senha !== form.confirmarSenha) return "As senhas não coincidem";
    return null;
  }

  function avancar() {
    const err = validarStep1();
    if (err) {
      setError(err);
      return;
    }
    setStep(2);
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const err = validarStep2();
    if (err) {
      setError(err);
      return;
    }

    setLoading(true);
    setError("");

    try {
      const res = await fetch("/api/auth/cadastro", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          nome: form.nome,
          empresa: form.empresa,
          email: form.email,
          senha: form.senha,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.error || "Erro ao criar conta");
        return;
      }

      router.push("/dashboard");
    } catch {
      setError("Erro de conexão. Tente novamente.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div style={styles.root}>
      <aside style={styles.aside}>
        <div style={styles.asideLogo}>
          <HardHat size={36} color="white" />
          <span style={styles.asideBrand}>Engetech</span>
        </div>

        <div style={styles.asideContent}>
          <h1 style={styles.asideTitle}>Gerencie suas obras com clareza</h1>
          <p style={styles.asideSubtitle}>
            Controle orçamentos, equipes, RDOs e o portal do cliente — tudo em
            um só lugar.
          </p>

          <ul style={styles.beneficios}>
            {[
              "Diário de obra digital (RDO)",
              "Portal do cliente sem login",
              "Controle financeiro por obra",
              "Acesso via celular ou desktop",
            ].map((item) => (
              <li key={item} style={styles.beneficioItem}>
                <CheckCircle2 size={16} color="rgba(255,255,255,0.7)" />
                <span>{item}</span>
              </li>
            ))}
          </ul>
        </div>

        <p style={styles.asideFooter}>Engetech Soluções © 2025</p>
      </aside>

      <main style={styles.main}>
        <div style={styles.formBox}>
          <div style={styles.steps}>
            <div style={stepDot(step >= 1)}>1</div>
            <div style={stepLine(step >= 2)} />
            <div style={stepDot(step >= 2)}>2</div>
          </div>

          <h2 style={styles.title}>
            {step === 1 ? "Sobre você e sua empresa" : "Acesso à plataforma"}
          </h2>
          <p style={styles.subtitle}>
            {step === 1
              ? "Vamos começar com algumas informações básicas"
              : "Defina seu e-mail e senha de acesso"}
          </p>

          <form
            onSubmit={
              step === 1
                ? (e) => {
                    e.preventDefault();
                    avancar();
                  }
                : handleSubmit
            }
          >
            {step === 1 && (
              <>
                <Field
                  icon={<User size={16} />}
                  label="Nome completo"
                  name="nome"
                  placeholder="Pedro Alves"
                  value={form.nome}
                  onChange={handleChange}
                  autoFocus
                />
                <Field
                  icon={<Building2 size={16} />}
                  label="Nome da empresa"
                  name="empresa"
                  placeholder="Engetech Soluções LTDA"
                  value={form.empresa}
                  onChange={handleChange}
                />
              </>
            )}

            {step === 2 && (
              <>
                <Field
                  icon={<Mail size={16} />}
                  label="E-mail"
                  name="email"
                  type="email"
                  placeholder="pedro@engetech.com.br"
                  value={form.email}
                  onChange={handleChange}
                  autoFocus
                />
                <Field
                  icon={<Lock size={16} />}
                  label="Senha"
                  name="senha"
                  type={showPassword ? "text" : "password"}
                  placeholder="Mínimo 6 caracteres"
                  value={form.senha}
                  onChange={handleChange}
                  suffix={
                    <button
                      type="button"
                      onClick={() => setShowPassword((v) => !v)}
                      style={styles.eyeBtn}
                    >
                      {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  }
                />
                <Field
                  icon={<Lock size={16} />}
                  label="Confirmar senha"
                  name="confirmarSenha"
                  type={showConfirm ? "text" : "password"}
                  placeholder="Repita a senha"
                  value={form.confirmarSenha}
                  onChange={handleChange}
                  suffix={
                    <button
                      type="button"
                      onClick={() => setShowConfirm((v) => !v)}
                      style={styles.eyeBtn}
                    >
                      {showConfirm ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  }
                />
              </>
            )}

            {error && <p style={styles.error}>{error}</p>}

            <button
              type="submit"
              disabled={loading}
              style={{
                ...styles.btn,
                opacity: loading ? 0.7 : 1,
                cursor: loading ? "not-allowed" : "pointer",
              }}
            >
              {loading ? (
                "Criando conta..."
              ) : (
                <>
                  {step === 1 ? "Continuar" : "Criar minha conta"}
                  <ArrowRight size={16} />
                </>
              )}
            </button>

            {step === 2 && (
              <button
                type="button"
                onClick={() => setStep(1)}
                style={styles.btnBack}
              >
                ← Voltar
              </button>
            )}
          </form>

          <p style={styles.loginLink}>
            Já tem uma conta?{" "}
            <Link href="/login" style={styles.link}>
              Fazer login
            </Link>
          </p>
        </div>
      </main>
    </div>
  );
}

function Field({
  icon,
  label,
  suffix,
  ...props
}: React.InputHTMLAttributes<HTMLInputElement> & {
  icon: React.ReactNode;
  label: string;
  suffix?: React.ReactNode;
}) {
  return (
    <div style={styles.field}>
      <label style={styles.label}>{label}</label>
      <div style={styles.inputWrap}>
        <span style={styles.inputIcon}>{icon}</span>
        <input style={styles.input} {...props} />
        {suffix}
      </div>
    </div>
  );
}

