/* ═══════════════════════════════════════
   TOKENS HSL — TEMA CLARO
═══════════════════════════════════════ */
:root {
  /* Base */
  --radius: 10px;
  --radius-sm: 6px;
  --radius-lg: 14px;
  --radius-full: 9999px;

  /* Cores primárias */
  --primary-h: 213;
  --primary-s: 70%;
  --primary-l: 39%;
  --primary: hsl(var(--primary-h), var(--primary-s), var(--primary-l));
  --primary-hover: hsl(var(--primary-h), var(--primary-s), 32%);
  --primary-light: hsl(var(--primary-h), 70%, 95%);
  --primary-text: hsl(var(--primary-h), 70%, 25%);

  /* Superfícies */
  --bg-app: hsl(220, 20%, 97%);
  --bg-card: hsl(0, 0%, 100%);
  --bg-card-hover: hsl(220, 20%, 98%);
  --bg-input: hsl(0, 0%, 100%);
  --bg-muted: hsl(220, 15%, 95%);
  --bg-sidebar: hsl(0, 0%, 100%);

  /* Bordas */
  --border: hsl(220, 13%, 91%);
  --border-strong: hsl(220, 13%, 82%);
  --border-input: hsl(220, 13%, 87%);

  /* Texto */
  --text-primary: hsl(222, 47%, 11%);
  --text-secondary: hsl(220, 9%, 46%);
  --text-muted: hsl(220, 9%, 64%);
  --text-on-primary: hsl(223, 7%, 19%);

  /* Status */
  --success-h: 158;
  --success: hsl(var(--success-h), 64%, 38%);
  --success-light: hsl(var(--success-h), 64%, 94%);
  --success-text: hsl(var(--success-h), 64%, 22%);

  --warning-h: 38;
  --warning: hsl(var(--warning-h), 92%, 50%);
  --warning-light: hsl(var(--warning-h), 92%, 94%);
  --warning-text: hsl(var(--warning-h), 80%, 28%);

  --danger-h: 0;
  --danger: hsl(var(--danger-h), 72%, 51%);
  --danger-light: hsl(var(--danger-h), 72%, 95%);
  --danger-text: hsl(var(--danger-h), 72%, 30%);

  --purple-h: 258;
  --purple: hsl(var(--purple-h), 60%, 52%);
  --purple-light: hsl(var(--purple-h), 60%, 95%);
  --purple-text: hsl(var(--purple-h), 60%, 28%);

  /* Sombras */
  --shadow-sm:
    0 1px 3px hsl(220, 13%, 0%, 0.08), 0 1px 2px hsl(220, 13%, 0%, 0.04);
  --shadow-md:
    0 4px 12px hsl(220, 13%, 0%, 0.08), 0 2px 4px hsl(220, 13%, 0%, 0.04);
  --shadow-lg:
    0 8px 24px hsl(220, 13%, 0%, 0.1), 0 4px 8px hsl(220, 13%, 0%, 0.06);
  --shadow-sidebar: 1px 0 0 var(--border);

  /* Transições */
  --transition: 150ms ease;
  --transition-slow: 250ms ease;
}

/* ═══════════════════════════════════════
   TOKENS HSL — TEMA ESCURO
═══════════════════════════════════════ */
[data-theme="dark"] {
  --primary-l: 55%;
  --primary: hsl(var(--primary-h), var(--primary-s), var(--primary-l));
  --primary-hover: hsl(var(--primary-h), var(--primary-s), 62%);
  --primary-light: hsl(var(--primary-h), 40%, 18%);
  --primary-text: hsl(var(--primary-h), 70%, 75%);

  --bg-app: hsl(222, 20%, 10%);
  --bg-card: hsl(222, 18%, 13%);
  --bg-card-hover: hsl(222, 18%, 15%);
  --bg-input: hsl(222, 18%, 16%);
  --bg-muted: hsl(222, 15%, 17%);
  --bg-sidebar: hsl(222, 20%, 11%);

  --border: hsl(217, 4%, 59%);
  --border-strong: hsl(222, 15%, 28%);
  --border-input: hsl(222, 15%, 25%);

  --text-primary: hsl(220, 20%, 94%);
  --text-secondary: hsl(220, 10%, 60%);
  --text-muted: hsl(220, 10%, 42%);

  --success: hsl(var(--success-h), 55%, 52%);
  --success-light: hsl(var(--success-h), 40%, 18%);
  --success-text: hsl(var(--success-h), 55%, 72%);

  --warning: hsl(var(--warning-h), 80%, 55%);
  --warning-light: hsl(var(--warning-h), 40%, 18%);
  --warning-text: hsl(var(--warning-h), 80%, 72%);

  --danger: hsl(var(--danger-h), 65%, 58%);
  --danger-light: hsl(var(--danger-h), 40%, 18%);
  --danger-text: hsl(var(--danger-h), 65%, 75%);

  --purple: hsl(var(--purple-h), 55%, 65%);
  --purple-light: hsl(var(--purple-h), 40%, 18%);
  --purple-text: hsl(var(--purple-h), 55%, 78%);

  --shadow-sm: 0 1px 3px hsl(0, 0%, 0%, 0.3);
  --shadow-md: 0 4px 12px hsl(0, 0%, 0%, 0.35);
  --shadow-lg: 0 8px 24px hsl(0, 0%, 0%, 0.4);
  --shadow-sidebar: 1px 0 0 var(--border);
}

/* ═══════════════════════════════════════
   RESET & BASE
═══════════════════════════════════════ */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  -webkit-font-smoothing: antialiased;
