/* ═══════════════════════════════════════
   RESPONSIVO
═══════════════════════════════════════ */
@media (max-width: 768px) {
  .sidebar-desktop {
    display: none !important;
  }
  .main-content {
    margin-left: 0 !important;
  }
  .mobile-header {
    display: flex !important;
  }
  .desktop-header {
    display: none !important;
  }
