}

/* ═══════════════════════════════════════
   ANIMAÇÕES
═══════════════════════════════════════ */
@keyframes modalIn {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideIn {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(0);
  }
}

.animate-fade {
  animation: fadeIn 200ms ease forwards;
}

/* Input focus */
input:focus,
select:focus,
textarea:focus {
  border-color: var(--primary) !important;
  box-shadow: 0 0 0 3px
    hsl(var(--primary-h), var(--primary-s), var(--primary-l), 0.15) !important;
  outline: none;
}

/* Botão hover */
button:active {
  transform: scale(0.98);
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--border-strong);
  border-radius: 999px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* Sidebar link hover */
nav a:hover {
  background: var(--bg-muted) !important;
  color: var(--text-primary) !important;
}

/* ═══════════════════════════════════════
   MOBILE — regras globais de responsividade
   Aplicadas automaticamente em todas as páginas
═══════════════════════════════════════ */

/* Tabelas — scroll horizontal no mobile em vez de quebrar */
.table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  /* Fade visual nas bordas para indicar scroll */
  mask-image: linear-gradient(to right, black 90%, transparent 100%);
  -webkit-mask-image: linear-gradient(to right, black 90%, transparent 100%);
}

@media (max-width: 767px) {
  /* ── Formulários ── */
  /* Todo grid de formulário vai para coluna única no mobile */
  [data-form-grid] {
    grid-template-columns: 1fr !important;
  }
  /* Campos que ocupavam a linha toda continuam ocupando */
  [data-form-grid] [data-full] {
    grid-column: 1 !important;
  }

  /* ── Cards em grid ── */
  [data-grid="4"] {
    grid-template-columns: 1fr 1fr !important;
    gap: 8px !important;
  }
  [data-grid="3"] {
    grid-template-columns: 1fr !important;
  }
  [data-grid="2"] {
    grid-template-columns: 1fr !important;
  }

  /* ── Tabelas ── */
  /* Esconder colunas menos importantes no mobile */
  .hide-mobile {
    display: none !important;
  }
  /* Texto menor nas tabelas para caber mais info */
  table td,
  table th {
    font-size: 12px !important;
    padding: 8px 6px !important;
  }

  /* ── Modais ── */
  /* Modal ocupa quase a tela inteira no mobile */
  [data-modal-box] {
    width: 95vw !important;
    max-height: 85vh !important;
    overflow-y: auto !important;
    padding: 20px 16px !important;
  }

  /* ── Cards ── */
  /* Padding menor nos cards mobile */
  [data-card] {
    padding: 14px !important;
  }

  /* ── Botões de ação em linha ── */
  /* Grupos de botões viram coluna no mobile */
  .btn-group-mobile {
    flex-direction: column !important;
    width: 100% !important;
  }
  .btn-group-mobile > * {
    width: 100% !important;
    justify-content: center !important;
  }

  /* ── Pipeline kanban ── */
  /* Scroll horizontal em vez de quebrar */
  [data-kanban] {
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch !important;
    flex-wrap: nowrap !important;
  }
  [data-kanban-col] {
    min-width: 260px !important;
    flex-shrink: 0 !important;
  }

  /* ── Gantt / Cronograma ── */
  [data-gantt-header] {
    grid-template-columns: repeat(3, 1fr) !important;
    overflow-x: auto;
  }

  /* ── Typography ── */
  h1 {
    font-size: 18px !important;
  }
  h2 {
    font-size: 15px !important;
  }

  /* ── Métricas superiores do dashboard ── */
  [data-metrics] {
    grid-template-columns: 1fr 1fr !important;
    gap: 8px !important;
  }
  [data-metrics] [data-metric-value] {
    font-size: 18px !important;
  }
}

/* ── Tablet (768–1023px) ── */
@media (min-width: 768px) and (max-width: 1023px) {
  [data-grid="4"] {
    grid-template-columns: 1fr 1fr !important;
  }
  [data-grid="3"] {
    grid-template-columns: 1fr 1fr !important;
  }
  [data-metrics] {
    grid-template-columns: 1fr 1fr !important;
  }
}

/* ── Touch targets mínimos (WCAG 2.5.5) ── */
@media (pointer: coarse) {
  button,
  a[href],
  [role="button"] {
    min-height: 44px;
    min-width: 44px;
  }
  /* Exceção: botões inline pequenos em tabelas */
  table button {
    min-height: 32px;
    min-width: 32px;
  }
}

