  percentual: number;
}
interface Etapa {
  nome: string;
  status: string;
  percentual: number;
  inicioPlano: string;
  fimPlano: string;
  subtarefas: Subtarefa[];
}
interface Atividade {
  descricao: string;
  percentual: number;
  status: string;
}
interface DiarioItem {
  data: string;
  clima: string;
  resumo?: string;
  atividades: Atividade[];
}
interface Portal {
  titulo: string;
  cliente: string;
  tipo: string;
  status: string;
  endereco?: string;
  inicio: string;
  previsaoFim: string;
  etapas: Etapa[];
  diario: DiarioItem[];
}

const STATUS_CFG: Record<
  string,
