    return;
  }
  if (!demo) {
    console.log("❌ Demo não encontrado");
    return;
  }

  console.log(`✅ Admin ID: ${admin.id}`);
  console.log(`✅ Demo  ID: ${demo.id}`);

  // Usar SQL puro para atualizar — sem depender dos tipos do Prisma
  const tabelas = [
    "Cliente",
    "Obra",
    "Fornecedor",
    "Orcamento",
    "Diarista",
    "Material",
    "GastoEsporadico",
